/** All translations for zizhitongjian ch.021 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起玄黓涒灘，盡玄黓敦牂，凡十一年。", literal: "From Xuanyi Tuantan through Xuanyi Dunyang; eleven years in all.", idiomatic: "From Xuanyi Tuantan through Xuanyi Dunyang—eleven years in all." },
  { zh: "1冬，十月，上行幸雍，祠五畤；", literal: "1. In winter, the tenth month, the emperor traveled in favor to Yong and sacrificed at the Five Altars;", idiomatic: "1. In winter, the tenth month, the emperor traveled to Yong and sacrificed at the Five Altars;" },
  { zh: "還，祝祠泰一，以拜德星。", literal: "on returning, he prayed and sacrificed to the Grand Unity, thereby paying homage to the Virtue Star.", idiomatic: "on his return he prayed and sacrificed to the Grand Unity to pay homage to the Virtue Star." },
  { zh: "----2春，正月，公孫卿言：「見神人東萊山，若-{云}-欲見天子。", literal: "----2 In spring, the first month, Gongsun Qing said: \"I saw a spirit-man on Mount Donglai who seemed -{云}- to wish to see the Son of Heaven.", idiomatic: "----2 In spring, the first month, Gongsun Qing said, \"I saw a spirit-man on Mount Donglai who seemed about to wish to see the Son of Heaven." },
  { zh: "」天子於是幸緱氏城，拜卿為中大夫，遂至東萊，宿留之，數日，無所見，見大人跡-{云}-。", literal: "\" The Son of Heaven thereupon favored Gou'shi city, appointed Qing as Palace Grandee, and proceeded to Donglai, lodging there several days without seeing anything—only the footprints of a great man -{云}-.", idiomatic: "\" The emperor thereupon visited Gou'shi, appointed Qing Palace Grandee, and went on to Donglai, where he lodged several days without seeing anything—only the footprints of a great man -{云}-." },
  { zh: "復遣方士求神怪，采芝藥，以千數。", literal: "He again dispatched masters of the methods to seek spirits and marvels and gather mushroom elixirs, numbering in the thousands.", idiomatic: "He again dispatched masters of the methods to seek spirits and marvels and gather mushroom elixirs, numbering in the thousands." },
  { zh: "時歲旱，天子既出無名，乃禱萬里沙。", literal: "At that time the year was drought-stricken; the Son of Heaven having gone forth without a stated purpose, he thereupon prayed at Wanli Sands.", idiomatic: "The year was drought-stricken; the emperor having set out without a stated purpose, prayed at Wanli Sands." },
  { zh: "夏，四月，還，過祠泰山。", literal: "In summer, the fourth month, on returning he passed and sacrificed at Mount Tai.", idiomatic: "In summer, the fourth month, on his return he sacrificed at Mount Tai." },
  { zh: "----3初，河決瓠子，後二十餘歲不復塞，梁、楚之地尤被其害。", literal: "----3 At the outset, the Yellow River burst at Huzi; for more than twenty years afterward it was not blocked again, and the lands of Liang and Chu were especially afflicted.", idiomatic: "----3 At the outset the Yellow River burst at Huzi; for more than twenty years it was not blocked again, and Liang and Chu suffered worst." },
  { zh: "是歲，上使汲仁、郭昌二卿發卒數萬人塞瓠子河決。", literal: "That year, the emperor sent the two ministers Ji Ren and Guo Chang to raise several tens of thousands of conscripts to block the Huzi breach.", idiomatic: "That year the emperor sent Ministers Ji Ren and Guo Chang to raise tens of thousands of conscripts to block the Huzi breach." },
  { zh: "天子自泰山還，自臨決河，沈白馬、玉璧於河，令群臣、從官自將軍以下皆負薪，卒填決河。", literal: "The Son of Heaven, returning from Mount Tai, personally came to the breach, sank a white horse and jade disks in the river, and ordered the host of ministers and attendant officials from the generals down to all carry firewood—the soldiers filled the breach.", idiomatic: "Returning from Mount Tai, the emperor came in person to the breach, sank a white horse and jade disks in the river, and ordered every minister and attendant from the generals down to carry firewood until the soldiers had filled the breach." },
  { zh: "築宮其上，名曰宣防宮。", literal: "He built a palace upon it, named Xuanfang Palace.", idiomatic: "He built a palace upon it and named it Xuanfang Palace." },
  { zh: "導河北行二渠，復禹舊跡，而梁、楚之地復寧，無水災。", literal: "He guided the Yellow River north to run in two channels, restoring Yu's old course, and the lands of Liang and Chu were again at peace, without flood disaster.", idiomatic: "He guided the Yellow River north into two channels, restoring Yu's old course, and Liang and Chu were at peace again, without flood disaster." },
  { zh: "----4上還長安。", literal: "----4 The emperor returned to Chang'an.", idiomatic: "----4 The emperor returned to Chang'an." },
  { zh: "----5初令越巫祠上帝、百鬼，而用雞卜。", literal: "----5 For the first time he ordered Yue shamans to sacrifice to the High God and the hundred ghosts, and used chicken divination.", idiomatic: "----5 For the first time he ordered Yue shamans to sacrifice to the High God and the hundred ghosts, and used chicken divination." },
  { zh: "----6公孫卿言仙人好樓居，於是上令長安作蜚廉、桂觀，甘泉作益壽、延壽觀，使卿持節設具而候神人。", literal: "----6 Gongsun Qing said that immortals love to dwell in towers; thereupon the emperor ordered Feilian and Gui Terrace built in Chang'an, and Yishou and Yanshou terraces built at Ganquan, and sent Qing with credentials to set out offerings and await the spirit-man.", idiomatic: "----6 Gongsun Qing said immortals love tower dwellings; the emperor ordered Feilian and Gui Terrace built in Chang'an and Yishou and Yanshou terraces at Ganquan, and sent Qing with credentials to set out offerings and await the spirit-man." },
  { zh: "又作通天莖台，置祠具其下。", literal: "He also built the Tongtian Stem Terrace and placed sacrificial implements below it.", idiomatic: "He also built the Tongtian Stem Terrace and placed sacrificial implements below it." },
  { zh: "更置甘泉前殿，益廣諸宮室。", literal: "He further established the front hall at Ganquan and greatly expanded the palaces and halls.", idiomatic: "He further established the front hall at Ganquan and greatly expanded the palaces and halls." },
  { zh: "----7初，全燕之世，嘗略屬真番、朝鮮，為置吏，築障塞。", literal: "----7 At the outset, in the age of united Yan, Yan had once roughly subordinated Zhenfan and Joseon, set officials over them, and built barrier fortifications.", idiomatic: "----7 At the outset, in the age of united Yan, Yan had once subordinated Zhenfan and Joseon, appointed officials, and built barrier fortifications." },
  { zh: "秦滅燕，屬遼東外徼。", literal: "When Qin destroyed Yan, they belonged to the outer marches of Liaodong.", idiomatic: "When Qin destroyed Yan, they fell within the outer marches of Liaodong." },
  { zh: "漢興，為其遠難守，復修遼東故塞，至浿水為界，屬燕。", literal: "When Han rose, because the region was remote and hard to hold, it restored the old Liaodong barriers, taking the Yalu River as the border, and they belonged to Yan.", idiomatic: "When Han rose, finding the region remote and hard to hold, it restored the old Liaodong barriers with the Yalu River as border, and they belonged to Yan." },
  { zh: "燕王盧綰反，入匈奴。", literal: "King Lu Wan of Yan rebelled and entered the Xiongnu.", idiomatic: "King Lu Wan of Yan rebelled and fled to the Xiongnu." },
  { zh: "燕人衛滿亡命，聚黨千餘人，椎髻、蠻夷服而東走出塞，渡浿水，居秦故空地上下障，稍役屬真番、朝鮮蠻夷及燕亡命者，王之，都王險。", literal: "The Yan man Wei Man, a fugitive, gathered a party of more than a thousand men, wore topknots and barbarian dress, fled east out of the passes, crossed the Yalu, dwelt in Qin's old vacant lands between the upper and lower barriers, gradually subjugated the barbarians of Zhenfan and Joseon and Yan fugitives, made himself king, and established his capital at Wangxian.", idiomatic: "The Yan man Wei Man, a fugitive, gathered more than a thousand followers, wore topknots and barbarian dress, fled east beyond the passes, crossed the Yalu, settled in Qin's old vacant lands between the upper and lower barriers, gradually brought the barbarians of Zhenfan and Joseon and Yan fugitives under his rule, made himself king, and established his capital at Wangxian." },
  { zh: "會孝惠、高-{后}-時，天下初定，遼東太守即約：滿為外臣，保塞外蠻夷，無使盜邊；", literal: "It happened that in the time of Emperor Hui and Empress Gao -{后}-, when all under Heaven was newly settled, the Governor of Liaodong at once made a pact: Man was to be an outer minister, guarding the barbarians beyond the passes and not letting them raid the border;", idiomatic: "It happened that in the time of Emperor Hui and Empress Gao -{后}-, when the realm was newly settled, the Governor of Liaodong at once made a pact: Man was to be an outer minister, guarding the barbarians beyond the passes and keeping them from raiding the border;" },
  { zh: "諸蠻夷君欲入見天子，勿得禁止。", literal: "if the chieftains of the various barbarians wished to enter and see the Son of Heaven, he was not to forbid them.", idiomatic: "if barbarian chieftains wished to enter and see the Son of Heaven, he was not to forbid them." },
  { zh: "以故滿得以兵威財物侵降其旁小邑，真番、臨屯皆來服屬，方數千里。", literal: "For this reason Man was able with military might and wealth to invade and reduce the small settlements beside him; Zhenfan and Lintun all came to submit and belong to him—several thousand li square.", idiomatic: "Thus Man was able with military might and wealth to subdue neighboring settlements; Zhenfan and Lintun all submitted to him—several thousand li square." },
  { zh: "傳子至孫右渠，所誘漢亡人滋多，又未嘗入見，辰國欲上書見天子，又雍閼不通。", literal: "The line passed from son to grandson Youqu; the Han fugitives he enticed grew ever more numerous, and he had never entered to pay court; the state of Chen wished to submit a memorial and see the Son of Heaven, but was again blocked and obstructed.", idiomatic: "The line passed from son to grandson Youqu; the Han fugitives he enticed grew ever more numerous, and he had never come to court; the state of Chen wished to memorialize and see the Son of Heaven, but was blocked and obstructed." },
  { zh: "是歲，漢使涉何誘諭，右渠終不肯奉詔。", literal: "That year, Han sent She He to entice and instruct him, but Youqu in the end refused to obey the edict.", idiomatic: "That year Han sent She He to entice and instruct him, but Youqu refused to obey the edict." },
  { zh: "何去至界上，臨浿水，使御刺殺送何者朝鮮裨王長，即渡，馳入塞，遂歸報天子曰：「殺朝鮮將。", literal: "When He reached the border, facing the Yalu, he had his charioteer stab and kill Chang, the Joseon assistant king who was escorting him, then immediately crossed, galloped into the passes, and returned to report to the Son of Heaven: \"I killed a Joseon general.", idiomatic: "When He reached the border at the Yalu, he had his charioteer stab and kill Chang, the Joseon assistant king escorting him, crossed at once, galloped into the passes, and reported to the emperor, \"I killed a Joseon general." },
  { zh: "」上為其名美，即不詰，拜何為遼東東部都尉。", literal: "\" The emperor, pleased with the name of the deed, did not question him and appointed He Governor of the Eastern Division of Liaodong.", idiomatic: "\" The emperor, pleased with the deed's name, did not question him and appointed He Governor of the Eastern Division of Liaodong." },
  { zh: "朝鮮怨何，發兵襲攻殺何。", literal: "Joseon resented He and sent troops to raid and kill him.", idiomatic: "Joseon resented He and sent troops to raid and kill him." },
  { zh: "----8六月，甘泉房中產芝九莖，上為之赦天下。", literal: "----8 In the sixth month, nine stalks of mushroom grew in a room at Ganquan; the emperor thereupon proclaimed an amnesty for all under Heaven.", idiomatic: "----8 In the sixth month, nine stalks of mushroom grew in a room at Ganquan; the emperor proclaimed an amnesty for all under Heaven." },
  { zh: "----9上以旱為憂，公孫卿曰：「黃帝時，封則天旱，乾封三年。", literal: "----9 The emperor was troubled by drought; Gongsun Qing said: \"In the time of the Yellow Emperor, when the feng was performed there was drought; the Qianfeng lasted three years.", idiomatic: "----9 The emperor was troubled by drought; Gongsun Qing said, \"In the time of the Yellow Emperor, when the feng was performed there was drought; the Qianfeng lasted three years." },
  { zh: "」上乃下詔曰：「天旱，意乾封乎！", literal: "\" The emperor thereupon issued an edict: \"Heaven is dry—is it Qianfeng!", idiomatic: "\" The emperor issued an edict: \"Heaven is dry—is it Qianfeng!" },
  { zh: "」----10秋，作明堂於汶上。", literal: "\" ----10 In autumn, the Bright Hall was built on the Wen.", idiomatic: "\" ----10 In autumn, the Bright Hall was built on the Wen." },
  { zh: "----11上募天下死罪為兵，遣樓船將軍楊僕從齊浮渤海，左將軍荀彘出遼東，以討朝鮮。", literal: "----11 The emperor recruited men under sentence of death from all under Heaven as soldiers, sent Tower-Ship General Yang Pu to float across the Bohai from Qi, and Left General Xun Zhi to march out from Liaodong to attack Joseon.", idiomatic: "----11 The emperor recruited men under sentence of death from across the realm as soldiers, sent Tower-Ship General Yang Pu to sail from Qi across the Bohai, and Left General Xun Zhi out from Liaodong to attack Joseon." },
  { zh: "----12初，上使-{王然于}-以越破及誅南夷兵威喻滇王入朝。", literal: "----12 At the outset, the emperor sent -{Wang Ranyu}- with the military prestige of the defeat of Yue and the execution of the Southern Yi to instruct the King of Dian to enter court.", idiomatic: "----12 At the outset the emperor sent Wang Ranyu with the military prestige of Yue's defeat and the Southern Yi's punishment to persuade the King of Dian to come to court." },
  { zh: "滇王者，其眾數萬人，其旁東北有勞深、靡莫，皆同姓相杖，未肯聽。", literal: "The King of Dian had a host of several tens of thousands; to his northeast were Laoshen and Mimuo, all of the same surname supporting one another, who had not yet been willing to obey.", idiomatic: "The King of Dian had tens of thousands of followers; to his northeast were Laoshen and Mimuo, clansmen who supported one another and would not yet obey." },
  { zh: "勞深、靡莫數侵犯使者吏卒。", literal: "Laoshen and Mimuo repeatedly encroached upon and attacked the envoys' clerks and soldiers.", idiomatic: "Laoshen and Mimuo repeatedly attacked the envoys' clerks and soldiers." },
  { zh: "於是上遣將軍郭昌、中郎將衛廣發巴、蜀兵擊滅勞深、靡莫，以兵臨滇。", literal: "Thereupon the emperor sent General Guo Chang and Palace Gentleman-Commandant Wei Guang to raise troops from Ba and Shu, strike and destroy Laoshen and Mimuo, and press the army against Dian.", idiomatic: "The emperor then sent General Guo Chang and Palace Gentleman-Commandant Wei Guang to raise Ba and Shu troops, destroy Laoshen and Mimuo, and press the army against Dian." },
  { zh: "滇王舉國降，請置吏入朝，於是以為益州郡，賜滇王王印，復長其民。", literal: "The King of Dian surrendered with his whole state, requested that officials be set over him and that he enter court; thereupon it was made Yizhou Commandery, the King of Dian was given a king's seal, and he was again made to rule his people.", idiomatic: "The King of Dian surrendered his whole state, asked for officials and permission to come to court; it was made Yizhou Commandery, the king was given a royal seal, and he was again made to rule his people." },
  { zh: "是時，漢滅兩越，平西南夷，置初郡十七，且以其故俗治，毋賦稅。", literal: "At this time Han had destroyed the two Yues and pacified the Southwestern Yi, establishing seventeen new commanderies, governing them by their old customs and levying no taxes.", idiomatic: "At this time Han had destroyed the two Yues and pacified the Southwestern Yi, establishing seventeen new commanderies, governing them by their old customs and levying no taxes." },
  { zh: "南陽、漢中以往郡，各以地比，給初郡吏卒奉食、幣物、傳車、馬被具。", literal: "The commanderies from Nanyang and Hanzhong westward each according to proximity supplied the new commanderies' officials and soldiers with rations, goods, relay carts, horses, and equipment.", idiomatic: "Commanderies from Nanyang and Hanzhong westward each according to proximity supplied the new commanderies' officials and soldiers with rations, goods, relay carts, horses, and equipment." },
  { zh: "而初郡時時小反，殺吏，漢發南方吏卒往誅之，間歲萬餘人，費皆仰給大農。", literal: "But the new commanderies from time to time rebelled on a small scale and killed officials; Han sent southern officials and soldiers to execute them—every other year more than ten thousand men—and the expense all depended on the Grand Agriculture Minister.", idiomatic: "But the new commanderies rebelled in small outbreaks and killed officials; Han sent southern troops to punish them—more than ten thousand men every other year—and the expense all fell on the Grand Agriculture Minister." },
  { zh: "大農以均輸、調鹽鐵助賦，故能贍之。", literal: "The Grand Agriculture Minister, with equalizing transport and the salt-and-iron adjustments aiding the levies, was therefore able to supply it.", idiomatic: "The Grand Agriculture Minister, aided by equalizing transport and salt-and-iron adjustments, was able to meet the cost." },
  { zh: "然兵所過，縣為以訾給毋乏而已，不也言擅賦法矣。", literal: "Yet where the army passed, the districts merely assessed supplies so there would be no shortage—that was all; they did not also speak of unauthorized tax statutes.", idiomatic: "Yet where the army passed, districts merely assessed supplies so there would be no shortage—that was all; they dared not speak of unauthorized levies." },
  { zh: "----13是歲，以御史中丞南陽杜周為廷尉。", literal: "----13 That year, Du Zhou of Nanyang, Vice Censor-in-Chief, was made Commandant of Justice.", idiomatic: "----13 That year Du Zhou of Nanyang, Vice Censor-in-Chief, was made Commandant of Justice." },
  { zh: "周外寬，內深次骨，其治大放張湯。", literal: "Zhou was outwardly lenient but inwardly deep to the bone; his governance greatly followed Zhang Tang's model.", idiomatic: "Zhou was outwardly lenient but inwardly ruthless; his governance greatly followed Zhang Tang's model." },
  { zh: "時詔獄益多，二千石系者，新故相因，不減百餘人；", literal: "At that time imperial-prison cases grew ever more numerous; those imprisoned at the two-thousand-bushel rank, new and old succeeding one another, were no fewer than a hundred-odd;", idiomatic: "Imperial-prison cases grew ever more numerous; officials at the two-thousand-bushel rank in custody, new and old succeeding one another, numbered no fewer than a hundred;" },
  { zh: "廷尉一歲至千餘章，章大者連逮證案數百，小者數十人；", literal: "the Commandant of Justice in one year received more than a thousand memorials; in large cases the connected arrests and evidence ran to several hundred, in small ones to several tens;", idiomatic: "the Commandant of Justice in one year received more than a thousand cases; large cases involved hundreds in connected arrests, small ones dozens;" },
  { zh: "遠者數千、近者數百里會獄。", literal: "those from afar several thousand, those from near several hundred li, were gathered for trial.", idiomatic: "defendants were gathered for trial from thousands of li away, or from hundreds." },
  { zh: "廷尉及中都官詔獄逮至六七萬人，吏所增加，十萬餘人。", literal: "Those arrested in the Commandant of Justice's and the capital officials' imperial prisons reached sixty or seventy thousand; with those the clerks added, more than a hundred thousand.", idiomatic: "Those arrested in the Commandant of Justice's and capital officials' imperial prisons reached sixty or seventy thousand; with those the clerks added, more than a hundred thousand." },
  { zh: "1冬，十二月，雷；", literal: "1. In winter, the twelfth month, there was thunder;", idiomatic: "1. In winter, the twelfth month, there was thunder;" },
  { zh: "雨雹，大如馬頭。", literal: "hail fell as large as horses' heads.", idiomatic: "hail fell as large as horses' heads." },
  { zh: "----2上遣將軍趙破奴擊車師。", literal: "----2 The emperor sent General Zhao Poniang to attack the Wusun state of Cheshi.", idiomatic: "----2 The emperor sent General Zhao Poniang to attack Cheshi." },
  { zh: "破奴與輕騎七百餘先至，虜樓蘭王，遂破車師，因舉兵威以困烏孫、大宛之屬。", literal: "Poniang with more than seven hundred light cavalry arrived first, captured the King of Loulan, then broke Cheshi, and thereby raised military prestige to press Wusun, Dayuan, and the like.", idiomatic: "Poniang with more than seven hundred light cavalry arrived first, captured the King of Loulan, broke Cheshi, and raised military prestige to press Wusun, Dayuan, and the like." },
  { zh: "春，正月，甲申，封破奴為浞野侯。", literal: "In spring, the first month, on jiashen, Poniang was enfeoffed as Marquis of Zhuoye.", idiomatic: "In spring, the first month, on jiashen, Poniang was enfeoffed as Marquis of Zhuoye." },
  { zh: "王恢佐破奴擊樓蘭，封恢為浩侯。", literal: "Wang Hui assisted Poniang in attacking Loulan and was enfeoffed as Marquis of Hao.", idiomatic: "Wang Hui assisted Poniang in attacking Loulan and was enfeoffed as Marquis of Hao." },
  { zh: "於是酒泉列亭障至玉門矣。", literal: "Thereupon from Jiuquan beacon towers and barriers were set in line as far as Jade Gate.", idiomatic: "Thereupon beacon towers and barriers were set in line from Jiuquan as far as Jade Gate." },
  { zh: "----3初作角抵戲、魚龍曼延之屬。", literal: "----3 For the first time wrestling contests and fish-dragon spreading displays and the like were performed.", idiomatic: "----3 For the first time wrestling contests and fish-dragon pageants and the like were performed." },
  { zh: "----4漢兵入朝鮮境，朝鮮王右渠發兵距險。", literal: "----4 Han troops entered Joseon territory; King Youqu of Joseon sent troops to hold the passes.", idiomatic: "----4 Han troops entered Joseon; King Youqu sent troops to hold the passes." },
  { zh: "樓船將軍將齊兵七千人先至王險。", literal: "Tower-Ship General led seven thousand Qi troops and arrived first at Wangxian.", idiomatic: "Tower-Ship General led seven thousand Qi troops and arrived first at Wangxian." },
  { zh: "右渠城守，窺知樓船軍少，即出城擊樓船；", literal: "Youqu defended the city; spying and learning that the tower-ship army was few, he at once came out and attacked the tower-ships;", idiomatic: "Youqu defended the city; seeing the tower-ship force was small, he sallied out to attack them;" },
  { zh: "樓船軍敗散，遁山中十餘日，稍求退散卒，復聚。", literal: "the tower-ship army was defeated and scattered, hid in the mountains more than ten days, gradually sought out the scattered soldiers who had retreated, and gathered again.", idiomatic: "the tower-ship army was defeated and scattered, hid in the mountains more than ten days, gradually gathered the scattered survivors, and re-formed." },
  { zh: "左將軍擊朝鮮浿水西軍，未能破。", literal: "Left General attacked the Joseon army west of the Yalu but could not break it.", idiomatic: "Left General attacked the Joseon army west of the Yalu but could not break it." },
  { zh: "天子為兩將未有利，乃使衛山因兵威往諭右渠。", literal: "The Son of Heaven, because the two generals had no success, sent Wei Shan with military prestige to go instruct Youqu.", idiomatic: "Because the two generals had no success, the emperor sent Wei Shan with the army's prestige to instruct Youqu." },
  { zh: "右渠見使者，頓首謝：「願降，恐兩將詐殺臣，今見信節，請復降。", literal: "Youqu met the envoy, knocked his head and apologized: \"I wish to surrender but fear the two generals will deceive and kill me; now seeing the credentials of trust, I beg to surrender again.", idiomatic: "Youqu met the envoy, knocked his head and said, \"I wish to surrender but fear the two generals will trick and kill me; now seeing your credentials of trust, I beg to surrender again." },
  { zh: "」遣太子入謝，獻馬五千匹，及饋軍糧；", literal: "\" He sent the heir to enter and apologize, presenting five thousand horses and provisions for the army;", idiomatic: "\" He sent the crown prince to apologize in person, presenting five thousand horses and army provisions;" },
  { zh: "人眾萬餘，持兵方渡浿水。", literal: "more than ten thousand men, armed, were just crossing the Yalu.", idiomatic: "more than ten thousand armed men were just crossing the Yalu." },
  { zh: "使者及左將軍疑其為變，謂太子：「已服降，宜令人毋持兵。", literal: "The envoy and Left General suspected treachery and told the heir: \"Having submitted, you ought to have your men not bear arms.", idiomatic: "The envoy and Left General suspected treachery and told the crown prince, \"Having submitted, you ought to order your men not to bear arms." },
  { zh: "」太子亦疑使者、左將軍詐殺之，遂不渡浿水，復引歸。", literal: "\" The heir also suspected the envoy and Left General would deceive and kill him, and therefore did not cross the Yalu but led his men back.", idiomatic: "\" The crown prince also suspected the envoy and Left General would trick and kill him, and did not cross the Yalu but led his men back." },
  { zh: "山還報天子，天子誅山。", literal: "Shan returned and reported to the Son of Heaven; the Son of Heaven executed Shan.", idiomatic: "Shan returned and reported; the emperor executed Shan." },
  { zh: "左將軍破浿水上軍，乃前至城下，圍其西北，樓船亦往會，居城南。", literal: "Left General broke the Joseon army above the Yalu, then advanced to below the city, besieging the northwest; the tower-ships also went to join him and encamped south of the city.", idiomatic: "Left General broke the Joseon army above the Yalu, advanced to the city, besieged the northwest, and the tower-ships joined him south of the city." },
  { zh: "右渠遂堅守城，數月未能下。", literal: "Youqu thereupon held the city firmly; for months it could not be taken.", idiomatic: "Youqu held the city firmly; for months it could not be taken." },
  { zh: "左將軍所將燕、代卒多勁悍，樓船將齊卒已嘗敗亡困辱，卒皆恐，將心慚，其圍右渠，常持和節。", literal: "The Yan and Dai soldiers under Left General were mostly fierce and strong; the Qi soldiers under the tower-ship general had already suffered defeat, flight, and humiliation—the soldiers were all afraid and the general's heart ashamed; in besieging Youqu they constantly held to conciliatory measures.", idiomatic: "Left General's Yan and Dai troops were mostly fierce; the tower-ship general's Qi troops had already suffered defeat and humiliation—the soldiers were afraid and the general ashamed; in besieging Youqu they constantly held to conciliation." },
  { zh: "左將軍急擊之，朝鮮大臣乃陰間使人私約降樓船，往來言尚未肯決。", literal: "Left General pressed the attack hotly; Joseon ministers thereupon sent men in secret to arrange surrender privately with the tower-ships, going back and forth—word had not yet been settled.", idiomatic: "Left General pressed the attack; Joseon ministers secretly sent men to arrange surrender with the tower-ships, going back and forth—nothing was yet settled." },
  { zh: "左將軍數與樓船期戰，樓船欲就其約，不會。", literal: "Left General repeatedly set dates with the tower-ships for battle; the tower-ships wished to follow their pact and did not join.", idiomatic: "Left General repeatedly set dates for joint battle; the tower-ships wished to honor their pact and did not join." },
  { zh: "左將軍亦使人求間隙降下朝鮮，朝鮮不肯，心附樓船，以故兩將不相能。", literal: "Left General also sent men seeking an opening to bring Joseon down in surrender; Joseon would not, their hearts attached to the tower-ships—for this reason the two generals could not get along.", idiomatic: "Left General also sent men seeking an opening to accept surrender; Joseon would not, their hearts with the tower-ships—for this reason the two generals could not cooperate." },
  { zh: "左將軍心意樓船前有失軍罪，今與朝鮮私善，而又不降，疑其有反計，未敢發。", literal: "Left General thought in his heart that the tower-ships had earlier the crime of losing the army, now were on private good terms with Joseon, and yet did not surrender—he suspected them of a plot to rebel and did not dare act.", idiomatic: "Left General thought the tower-ships had earlier lost the army, now were on private terms with Joseon, and yet did not surrender—he suspected treason and did not dare act." },
  { zh: "天子以兩將圍城乖異，兵久不決，使濟南太守公孫遂往正之，有便宜得以從事。", literal: "The Son of Heaven, because the two generals besieging the city were at odds and the army long undecided, sent the Governor of Jinan Gongsun Sui to correct them, with authority to act as expedient.", idiomatic: "Because the two generals besieging the city were at odds and the army long undecided, the emperor sent Governor of Jinan Gongsun Sui to correct them, with authority to act as expedient." },
  { zh: "遂至，左將軍曰：「朝鮮當下，久之不下者，樓船數期不會。", literal: "When Sui arrived, Left General said: \"Joseon ought to fall; the reason it has long not fallen is that the tower-ships repeatedly set dates and did not join.", idiomatic: "When Sui arrived, Left General said, \"Joseon ought to have fallen; the reason it has not is that the tower-ships repeatedly set dates and did not join." },
  { zh: "」具以素所意告，曰：「今如此不取，恐為大害。", literal: "\" He fully told what he had long thought and said: \"If we do not seize them now like this, I fear it will be a great harm.", idiomatic: "\" He fully told his long-held suspicions and said, \"If we do not seize them now, I fear great harm." },
  { zh: "」遂亦以為然，乃以節召樓船將軍入左將軍營計事，即命左將軍麾下執樓船將軍，并其軍。", literal: "\" Sui also thought it so; he thereupon with credentials summoned the tower-ship general into Left General's camp to consult, and at once ordered Left General's subordinates to seize the tower-ship general and merge his army.", idiomatic: "\" Sui agreed; he summoned the tower-ship general into Left General's camp to consult, and at once ordered Left General's men to seize him and merge his army." },
  { zh: "以報天子，天子誅遂。", literal: "He reported to the Son of Heaven; the Son of Heaven executed Sui.", idiomatic: "He reported to the emperor; the emperor executed Sui." },
  { zh: "左將軍已并兩軍，即急擊朝鮮。", literal: "Left General having merged the two armies, at once pressed the attack on Joseon.", idiomatic: "Left General, having merged the two armies, at once pressed the attack on Joseon." },
  { zh: "朝鮮相路人、相韓陰、尼谿相參、將軍王唊相與謀曰：「始欲降樓船，樓船今執，獨左將軍並將，戰益急，恐不能與戰；", literal: "Joseon chancellor Luren, chancellor Han Yin, Nixi chancellor Can, and general Wang Jia together plotted, saying: \"At first we wished to surrender to the tower-ships; the tower-ships are now seized; only Left General commands the merged armies and the fighting grows fiercer—we fear we cannot fight;", idiomatic: "Chancellors Luren and Han Yin, Nixi Chancellor Can, and General Wang Jia plotted together, saying, \"At first we wished to surrender to the tower-ships; the tower-ships are now seized; only Left General commands the merged armies and fighting grows fiercer—we fear we cannot fight;" },
  { zh: "王又不肯降。", literal: "the king also will not surrender.", idiomatic: "the king also will not surrender." },
  { zh: "」陰、唊、路人皆亡降漢，路人道死。", literal: "\" Yin, Jia, and Luren all fled and surrendered to Han; Luren died on the road.", idiomatic: "\" Yin, Jia, and Luren all fled and surrendered to Han; Luren died on the road." },
  { zh: "夏，尼谿參使人殺朝鮮王右渠來降。", literal: "In summer, Can of Nixi sent men to kill King Youqu of Joseon and came to surrender.", idiomatic: "In summer, Can of Nixi sent men to kill King Youqu and came to surrender." },
  { zh: "王險城未下，故右渠之大臣成己又反，復攻吏。", literal: "Wangxian city was not yet taken; therefore Youqu's minister Cheng Ji rebelled again and attacked the officials.", idiomatic: "Wangxian was not yet taken; Youqu's minister Cheng Ji rebelled again and attacked the officials." },
  { zh: "左將軍使右渠子長、降相路人之子最告諭其民。", literal: "Left General sent Youqu's son Chang and the surrendered chancellor Luren's son Zui to announce and instruct the people.", idiomatic: "Left General sent Youqu's son Chang and the surrendered chancellor Luren's son Zui to announce and instruct the people." },
  { zh: "誅成己。", literal: "Cheng Ji was executed.", idiomatic: "Cheng Ji was executed." },
  { zh: "以故遂定朝鮮，為樂浪、臨屯、玄菟、真番四郡。", literal: "For this reason Joseon was thereupon settled, made into the four commanderies of Lelang, Lintun, Xuantu, and Zhenfan.", idiomatic: "Thus Joseon was settled and made into the four commanderies of Lelang, Lintun, Xuantu, and Zhenfan." },
  { zh: "封參為澅清侯，陰為萩苴侯，唊為平州侯，長為幾侯，最以父死頗有功，為涅陽侯。", literal: "Can was enfeoffed as Marquis of Huqing, Yin as Marquis of Qiuju, Jia as Marquis of Pingzhou, Chang as Marquis of Ji, and Zui because his father died and he had some merit was made Marquis of Nieyang.", idiomatic: "Can was enfeoffed as Marquis of Huqing, Yin as Marquis of Qiuju, Jia as Marquis of Pingzhou, Chang as Marquis of Ji, and Zui—his father having died with some merit—as Marquis of Nieyang." },
  { zh: "左將軍徵至，坐爭功相嫉乖計，棄市。", literal: "When Left General was summoned back, he was convicted of contending for merit, mutual jealousy, and perverse planning, and abandoned in the marketplace.", idiomatic: "When Left General was summoned back, he was convicted of contending for merit, mutual jealousy, and thwarting the plan, and executed in the marketplace." },
  { zh: "樓船將軍亦坐兵至列口，當待左將軍，擅先縱，失亡多，當誅，贖為庶人。", literal: "The tower-ship general was also convicted: his troops had reached Liekou and ought to have awaited Left General, but he rashly advanced first, lost many, and deserved execution; he ransomed his life and became a commoner.", idiomatic: "The tower-ship general was also convicted: his troops had reached Liekou and ought to have awaited Left General, but he rashly advanced first and lost many men; he deserved execution but ransomed his life and became a commoner." },
  { zh: ":班固曰：玄菟、樂浪，本箕子所封。", literal: ": Ban Gu said: Xuantu and Lelang were originally the fiefs enfeoffed to Jizi.", idiomatic: ": Ban Gu said: Xuantu and Lelang were originally the fiefs enfeoffed to Jizi." },
  { zh: "昔箕子居朝鮮，教其民以禮義，田蠶織作，為民設禁八條，相殺，以當時償殺；", literal: "In former times Jizi dwelt in Joseon and taught its people ritual and righteousness, field work, silkworms, weaving, and crafts; he set for the people eight prohibitions: for mutual killing, compensation with killing in turn;", idiomatic: "In former times Jizi dwelt in Joseon and taught its people ritual and righteousness, farming, sericulture, weaving, and crafts; he set eight prohibitions for the people: for mutual killing, compensation with killing in turn;" },
  { zh: "相傷，以穀償；", literal: "for mutual wounding, compensation with grain;", idiomatic: "for mutual wounding, compensation with grain;" },
  { zh: "相盜者，男沒入為其家奴，女為婢；", literal: "for mutual theft, the man was confiscated and made the other family's slave, the woman a maidservant;", idiomatic: "for mutual theft, the man was confiscated as the other family's slave, the woman as maidservant;" },
  { zh: "欲自贖者人五十萬，雖免為民，俗猶羞之，嫁娶無所售。", literal: "Those wishing to redeem themselves paid five hundred thousand per person; though freed to be commoners, custom still shamed them, and in marriage none would take them.", idiomatic: "Those wishing to redeem themselves paid five hundred thousand cash per person; though freed to commoner status, custom still shamed them, and no one would marry them." },
  { zh: "是以其民終不相盜，無門戶之閉，婦人貞信不淫辟。", literal: "Therefore its people in the end did not steal from one another; there was no closing of doors and gates; women were chaste and faithful and did not go astray.", idiomatic: "Therefore its people did not steal from one another; doors and gates needed no closing; women were chaste and faithful and did not go astray." },
  { zh: "其田野飲食以籩豆，都邑頗放效吏，往往以杯器食。", literal: "In the fields and countryside they ate and drank with platters and stands; in the capital cities they largely imitated officials, and often ate with cups and vessels.", idiomatic: "In the countryside they ate and drank from platters and stands; in the cities they largely imitated officials and often ate with cups and vessels." },
  { zh: "郡初取吏於遼東，吏見民無閉臧，及賈人往者，夜則為盜，俗稍益薄，今於犯禁浸多，至六十餘條。", literal: "When the commandery first took clerks from Liaodong, the clerks saw the people did not close their stores, and when merchants went in, they stole by night; custom gradually grew thinner, and now violations of prohibitions have gradually increased to more than sixty articles.", idiomatic: "When the commandery first took clerks from Liaodong, the clerks saw the people did not lock their stores, and when merchants came they stole by night; custom gradually grew lax, and now violations of prohibitions have increased to more than sixty articles." },
  { zh: "可貴哉，仁賢之化也！", literal: "How admirable! The transformation of benevolence and worthiness!", idiomatic: "How admirable—the transformation wrought by benevolence and worthiness!" },
  { zh: "然東夷天性柔順，異於三方之外。", literal: "Yet the Eastern Yi by nature are gentle and compliant, unlike those outside the three directions.", idiomatic: "Yet the Eastern Yi are by nature gentle and compliant, unlike the peoples beyond the three directions." },
  { zh: "故孔子悼道不行，設浮桴於海，欲居九夷，有以也夫！", literal: "Therefore when Confucius grieved that the Way did not prevail, he set a raft on the sea and wished to dwell among the Nine Yi—there was reason in it!", idiomatic: "Therefore when Confucius grieved that the Way did not prevail, he spoke of setting a raft on the sea and dwelling among the Nine Yi—there was reason in it!" },
  { zh: "----5秋，七月，膠西於王端薨。", literal: "----5 In autumn, the seventh month, King Duan of Jiaoxi Yu died.", idiomatic: "----5 In autumn, the seventh month, King Duan of Jiaoxi Yu died." },
  { zh: "----6武都氐反，分徙酒泉。", literal: "----6 The Di of Wudu rebelled; they were dispersed and relocated to Jiuquan.", idiomatic: "----6 The Di of Wudu rebelled; they were dispersed and relocated to Jiuquan." },
  { zh: "1冬，十月，上行幸雍，祠五畤。", literal: "1 In winter, the tenth month, the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "1 In winter, the tenth month, the emperor traveled in favor to Yong and sacrificed at the Five Altars." },
  { zh: "通回中道，遂北出蕭關。", literal: "He opened the road through Huizhong, then went north out through Xiaoguan.", idiomatic: "He opened the road through Huizhong, then went north out through Xiaoguan." },
  { zh: "歷獨鹿、鳴澤，自代而還，幸河東。", literal: "He passed through Dulu and Ming Marsh, returned from Dai, and favored Hedong.", idiomatic: "He passed through Dulu and Ming Marsh, returned from Dai, and traveled in favor to Hedong." },
  { zh: "春，三月，祠后土，赦汾陰、夏陽、中都死罪以下。", literal: "In spring, the third month, he sacrificed to the Earth Lord and pardoned those below death offense in Fenyin, Xiayang, and Zhongdu.", idiomatic: "In spring, the third month, he sacrificed to the Earth Lord and pardoned those below death offense in Fenyin, Xiayang, and Zhongdu." },
  { zh: "----2夏，大旱。", literal: "----2 In summer, great drought.", idiomatic: "----2 In summer, there was great drought." },
  { zh: "----3匈奴自衛、霍度幕以來，希復為寇，遠徙北方，休養士馬，習射獵，數使使於漢，好辭甘言求請和親。", literal: "----3 Since Wei and Huo crossed the desert curtain, the Xiongnu rarely raided again; they moved far to the north, rested troops and horses, practiced archery and hunting, and repeatedly sent envoys to Han with pleasing words and sweet speech seeking peace marriage.", idiomatic: "----3 Since Wei and Huo crossed the desert curtain, the Xiongnu rarely raided again; they moved far north, rested troops and horses, practiced archery and hunting, and repeatedly sent envoys to Han with pleasing words seeking a peace marriage." },
  { zh: "漢使北地人王烏等窺匈奴，烏從其俗，去節入穹廬，單于愛之，佯許甘言，為遣其太子入漢為質。", literal: "Han sent Wang Wu of Beidi and others to spy on the Xiongnu; Wu followed their custom, removed his staff of office and entered the yurt; the Chanyu favored him and falsely promised sweet words, undertaking to send his crown prince into Han as hostage.", idiomatic: "Han sent Wang Wu of Beidi and others to reconnoiter the Xiongnu; Wu followed their custom, removed his staff of office and entered the yurt; the Chanyu favored him and falsely promised sweet words, undertaking to send his crown prince into Han as hostage." },
  { zh: "漢使楊信於匈奴，信不肯從其俗，單于曰：「故約漢嘗遣翁主，給繒絮食物有品，以和親，而匈奴亦不擾邊。", literal: "Han sent Yang Xin to the Xiongnu; Xin would not follow their custom; the Chanyu said: \"By the old agreement Han once sent a princess, supplied silk floss and food in fixed grades for peace marriage, and the Xiongnu also did not disturb the border.", idiomatic: "Han sent Yang Xin to the Xiongnu; Xin would not follow their custom; the Chanyu said, \"By the old agreement Han once sent a princess, supplied silk floss and food in fixed grades for a peace marriage, and the Xiongnu also did not disturb the border." },
  { zh: "今乃欲反古，令吾太子為質，無幾矣。", literal: "Now you wish to turn back the ancient way and make my crown prince a hostage—there is little hope of it.", idiomatic: "Now you wish to turn back the ancient way and make my crown prince a hostage—there is little hope of it." },
  { zh: "」信既歸，漢又使王烏往，而單于復諂以甘言，欲多得漢財物，紿謂王烏曰：「吾欲入漢見天子面，相約為兄弟。", literal: "\" After Xin returned, Han again sent Wang Wu; the Chanyu again flattered with sweet words, wishing to obtain more Han goods, and deceived Wu, saying: \"I wish to enter Han and see the Son of Heaven face to face and covenant as brothers.", idiomatic: "\" After Xin returned, Han again sent Wang Wu; the Chanyu again flattered with sweet words, wishing to obtain more Han goods, and deceived Wu, saying, \"I wish to enter Han and see the Son of Heaven face to face and covenant as brothers." },
  { zh: "」王烏歸報漢，漢為單于築邸於長安。", literal: "\" Wu returned and reported to Han; Han built a residence for the Chanyu in Chang'an.", idiomatic: "\" Wu returned and reported to Han; Han built a residence for the Chanyu in Chang'an." },
  { zh: "匈奴曰：「非得漢貴人使，吾不與誠語。", literal: "The Xiongnu said: \"Unless I get a Han noble envoy, I will not speak sincerely with you.", idiomatic: "The Xiongnu said, \"Unless I get a Han noble envoy, I will not speak sincerely with you." },
  { zh: "」匈奴使其貴人至漢，病，漢予藥，欲愈之，不幸而死。", literal: "\" The Xiongnu sent their noble to Han; he fell ill; Han gave medicine wishing to cure him, but unluckily he died.", idiomatic: "\" The Xiongnu sent their noble to Han; he fell ill; Han gave medicine wishing to cure him, but unluckily he died." },
  { zh: "漢使路充國佩二千石印綬往使，因送其喪，厚葬直數千金，曰：「此漢貴人也。", literal: "Han sent Lu Chongguo bearing a two-thousand-dan seal and cord as envoy, and thereby sent off his funeral; a lavish burial worth several thousand in gold was provided, saying: \"This was a Han noble.", idiomatic: "Han sent Lu Chongguo bearing a two-thousand-dan seal and cord as envoy and sent off his funeral; a lavish burial worth several thousand in gold was provided, saying, \"This was a Han noble." },
  { zh: "」單于以為漢殺吾貴使者，乃留路充國不歸。", literal: "\" The Chanyu thought Han had killed his noble envoy and detained Lu Chongguo, not letting him return.", idiomatic: "\" The Chanyu thought Han had killed his noble envoy and detained Lu Chongguo, not letting him return." },
  { zh: "諸所言者，單于特空紿王烏，殊無意入漢及遣太子。", literal: "All that had been said—the Chanyu had merely deceived Wang Wu in vain; he had absolutely no intent to enter Han or send the crown prince.", idiomatic: "All that had been said—the Chanyu had merely deceived Wang Wu in vain; he had absolutely no intent to enter Han or send the crown prince." },
  { zh: "於是匈奴數使奇兵侵犯漢邊。", literal: "Thereupon the Xiongnu repeatedly sent raiding detachments to invade the Han border.", idiomatic: "Thereupon the Xiongnu repeatedly sent raiding detachments to invade the Han border." },
  { zh: "乃拜郭昌為拔胡將軍，及浞野侯屯朔方以東，備胡。", literal: "Guo Chang was then invested as General Who Uproots the Barbarians, and together with the Marquis of Zhuoye he encamped east of Shuofang to guard against the barbarians.", idiomatic: "Guo Chang was then invested as General Who Uproots the Barbarians, and together with the Marquis of Zhuoye he encamped east of Shuofang to guard against the Xiongnu." },
  { zh: "1冬，上南巡狩，至於盛唐，望祀虞舜於九疑。", literal: "1 In winter, the emperor made a southern imperial tour to Sheng Tang, gazed and sacrificed to Shun of Yu at Jiuyi.", idiomatic: "1 In winter, the emperor made a southern imperial tour to Sheng Tang and gazed and sacrificed to Shun of Yu at Jiuyi." },
  { zh: "登灊天柱山，自尋陽浮江，親射蛟江中，獲之。", literal: "He ascended Qian's Tianzhu Mountain, from Xunyang floated on the river, personally shot a flood dragon in the river, and obtained it.", idiomatic: "He ascended Tianzhu Mountain in Qian, from Xunyang floated on the river, personally shot a flood dragon in the river, and obtained it." },
  { zh: "舳艫千里，薄樅陽而出，遂北至琅邪，並海，所過禮祠其名山大川。", literal: "Warships stretched a thousand li; pressing Zongyang he went out, then north to Langya along the sea; wherever he passed he performed rites and sacrificed to famous mountains and great rivers.", idiomatic: "Warships stretched a thousand li; pressing Zongyang he went out, then north to Langya along the sea; wherever he passed he performed rites and sacrificed to famous mountains and great rivers." },
  { zh: "春，三月，還至太山，增封。", literal: "In spring, the third month, he returned to Mount Tai and increased the feng and shan.", idiomatic: "In spring, the third month, he returned to Mount Tai and increased the feng and shan." },
  { zh: "甲子，始祀上帝於明堂，配以高祖，因朝諸侯王、列侯，受郡、國計。", literal: "On jiazi he first sacrificed to the Supreme Lord in the Bright Hall, paired with Gaozu, and thereby received in audience the feudal kings, princes, and marquises and received the accounts of the commanderies and kingdoms.", idiomatic: "On jiazi he first sacrificed to the Supreme Lord in the Bright Hall, paired with Gaozu, received in audience the feudal kings, princes, and marquises, and received the accounts of the commanderies and kingdoms." },
  { zh: "夏，四月，赦天下，所幸縣毋出今年租賦。", literal: "In summer, the fourth month, he pardoned all under Heaven; the counties he favored were not to pay this year's rent and levies.", idiomatic: "In summer, the fourth month, he pardoned all under Heaven; the counties he favored were exempted from this year's rent and levies." },
  { zh: "還，幸甘泉，郊泰畤。", literal: "Returning, he favored Ganquan and performed suburban sacrifice at the Grand Altar.", idiomatic: "Returning, he traveled in favor to Ganquan and performed suburban sacrifice at the Grand Altar." },
  { zh: "----2長平烈侯衛青薨。", literal: "----2 Marquis Lie of Changping Wei Qing died.", idiomatic: "----2 Marquis Lie of Changping Wei Qing died." },
  { zh: "起塚，像廬山。", literal: "A tomb mound was raised, modeled on Mount Lu.", idiomatic: "A tomb mound was raised, modeled on Mount Lu." },
  { zh: "----3上既攘卻胡、越，開地斥境，乃置交趾、朔方之州，及冀、幽、并、兗、徐、青、揚、荊、豫、益、涼等州，凡十三部，皆置刺史焉。", literal: "----3 The emperor having already repelled the Hu and Yue and opened lands and extended borders, he then established the provinces of Jiaozhi and Shuofang, and Ji, You, Bing, Yan, Xu, Qing, Yang, Jing, Yu, Yi, and Liang—thirteen departments in all—and in all set inspectors.", idiomatic: "----3 The emperor having already repelled the Hu and Yue and opened lands and extended borders, he then established the provinces of Jiaozhi and Shuofang, and Ji, You, Bing, Yan, Xu, Qing, Yang, Jing, Yu, Yi, and Liang—thirteen departments in all—and set inspectors in each." },
  { zh: "----4上以名臣文武欲盡，乃下詔曰：「蓋有非常之功，必待非常之人。", literal: "----4 The emperor, seeing that famous ministers' civil and military talent was nearly exhausted, thereupon issued an edict saying: \"For there to be extraordinary achievement, one must await extraordinary men.", idiomatic: "----4 The emperor, seeing that the civil and military talent of famous ministers was nearly exhausted, thereupon issued an edict saying, \"For there to be extraordinary achievement, one must await extraordinary men." },
  { zh: "故馬或奔踶而致千里，士或有負俗之累而立功名。", literal: "Therefore a horse may kick and rear yet run a thousand li; a gentleman may bear the burden of vulgar opinion yet establish merit and fame.", idiomatic: "Therefore a horse may kick and rear yet run a thousand li; a gentleman may bear the burden of vulgar opinion yet establish merit and fame." },
  { zh: "夫泛駕之馬，跅弛之士，亦在御之而已。", literal: "As for horses hard to drive and unbridled gentlemen, it lies only in how one handles them.", idiomatic: "As for horses hard to drive and unbridled gentlemen, it lies only in how one handles them." },
  { zh: "其令州、郡察吏、民有茂才、異等可為將、相及使絕國者。", literal: "Let the provinces and commanderies examine officials and people for flourishing talent and exceptional grade fit to be generals, chancellors, or envoys to distant states.", idiomatic: "Let the provinces and commanderies examine officials and people for outstanding talent and exceptional ability fit to be generals, chancellors, or envoys to distant states." },
  { zh: "」----1冬，上行幸回中。", literal: "\" ----1 In winter, the emperor traveled in favor to Huizhong.", idiomatic: "\" ----1 In winter, the emperor traveled in favor to Huizhong." },
  { zh: "----2春，作首山宮。", literal: "----2 In spring, Shoushan Palace was built.", idiomatic: "----2 In spring, Shoushan Palace was built." },
  { zh: "----3三月，行幸河東，祠-{后土}-，赦汾陰殊死以下。", literal: "----3 In the third month, he traveled in favor to Hedong, sacrificed to -{后土}-, and pardoned those below capital offense in Fenyin.", idiomatic: "----3 In the third month, he traveled in favor to Hedong, sacrificed to -{后土}-, and pardoned those below capital offense in Fenyin." },
  { zh: "----4漢既通西南夷，開五郡，欲地接以前通大夏，歲遣使十餘輩出此初郡，皆閉昆明，為所殺，奪幣物。", literal: "----4 Han having already opened communication with the Southwestern Yi and established five commanderies, wishing to link territory forward to reach Daxia, each year sent out more than ten missions from these new commanderies; all were blocked by Kunming, killed by them, and their goods seized.", idiomatic: "----4 Han having already opened communication with the Southwestern Yi and established five commanderies, wishing to link territory forward to reach Daxia, each year sent out more than ten missions from these new commanderies; all were blocked by Kunming, killed by them, and their goods seized." },
  { zh: "於是天子赦京師亡命，令從軍，遣拔胡將軍郭昌將以擊之，斬首數十萬。", literal: "Thereupon the Son of Heaven pardoned fugitives from the capital, ordered them to join the army, and dispatched General Who Uproots the Barbarians Guo Chang to lead troops against them; heads cut numbered several hundred thousand.", idiomatic: "Thereupon the emperor pardoned fugitives from the capital, ordered them to join the army, and dispatched General Who Uproots the Barbarians Guo Chang to lead troops against them; heads cut numbered several hundred thousand." },
  { zh: "後復遣使，竟不得通。", literal: "Later he again sent envoys, but in the end could not get through.", idiomatic: "Later he again sent envoys, but in the end could not get through." },
  { zh: "----5秋，大旱，蝗。", literal: "----5 In autumn, great drought and locusts.", idiomatic: "----5 In autumn, there was great drought and locusts." },
  { zh: "----6烏孫使者見漢廣大，歸報其國，其國乃益重漢。", literal: "----6 Wusun envoys saw Han's vast extent; returning they reported to their state, and their state thereupon valued Han the more.", idiomatic: "----6 Wusun envoys saw Han's vast extent; returning they reported to their state, and their state thereupon valued Han the more." },
  { zh: "匈奴聞烏孫與漢通，怒，欲擊之。", literal: "The Xiongnu heard Wusun communicated with Han, grew angry, and wished to attack them.", idiomatic: "The Xiongnu heard Wusun communicated with Han, grew angry, and wished to attack them." },
  { zh: "又其旁大宛、月氏之屬皆事漢，烏孫於是恐，使使願得尚漢公主，為昆弟。", literal: "Moreover Dayuan, the Yuezhi, and the like beside them all served Han; Wusun thereupon feared and sent envoys wishing to obtain marriage with a Han princess and become brothers.", idiomatic: "Moreover Dayuan, the Yuezhi, and the like beside them all served Han; Wusun thereupon feared and sent envoys wishing to obtain marriage with a Han princess and become brothers." },
  { zh: "天子與群臣議，許之。", literal: "The Son of Heaven deliberated with his ministers and assented.", idiomatic: "The emperor deliberated with his ministers and assented." },
  { zh: "烏孫以千匹馬往聘漢女。", literal: "Wusun sent a thousand horses to betroth a Han woman.", idiomatic: "Wusun sent a thousand horses to betroth a Han woman." },
  { zh: "漢以江都王建女細君為公主，往妻烏孫，贈送甚盛；", literal: "Han made the daughter of King Jian of Jiangdu, Xijun, a princess and sent her to marry Wusun with very lavish gifts;", idiomatic: "Han made the daughter of King Jian of Jiangdu, Xijun, a princess and sent her to marry Wusun with very lavish gifts;" },
  { zh: "烏孫王昆莫以為右夫人。", literal: "the King of Wusun Kunmo made her his right consort.", idiomatic: "the King of Wusun Kunmo made her his right consort." },
  { zh: "匈奴亦遣女妻昆莫，以為左夫人。", literal: "The Xiongnu also sent a woman to marry Kunmo and made her left consort.", idiomatic: "The Xiongnu also sent a woman to marry Kunmo and made her left consort." },
  { zh: "公主自治宮室居，歲時一再與昆莫會，置酒飲食。", literal: "The princess on her own built a palace residence; once or twice a year she met Kunmo, set out wine and food.", idiomatic: "The princess built her own palace residence; once or twice a year she met Kunmo and set out wine and food." },
  { zh: "昆莫年老，言語不通，公主悲愁思歸，天子聞而憐之，間歲遣使者以帷帳錦繡給遺焉。", literal: "Kunmo was old; speech did not communicate; the princess grieved and longed to return; the Son of Heaven heard and pitied her, and every other year sent envoys with curtains, brocades, and silks as gifts.", idiomatic: "Kunmo was old; they could not communicate; the princess grieved and longed to return; the emperor heard and pitied her, and every other year sent envoys with curtains, brocades, and silks as gifts." },
  { zh: "昆莫曰：「我老。", literal: "Kunmo said: \"I am old.", idiomatic: "Kunmo said, \"I am old." },
  { zh: "」欲使其孫岑娶尚公主。", literal: "\" He wished to have his grandson Cen marry and obtain the princess.", idiomatic: "\" He wished to have his grandson Cen marry the princess." },
  { zh: "公主不聽，上書言狀。", literal: "The princess would not consent and memorialized stating the circumstances.", idiomatic: "The princess would not consent and memorialized stating the circumstances." },
  { zh: "天子報曰：「從其國俗，欲與烏孫共滅胡。", literal: "The Son of Heaven replied: \"Follow their state's custom; I wish to join with Wusun to destroy the Hu.", idiomatic: "The emperor replied, \"Follow their state's custom; I wish to join with Wusun to destroy the Hu." },
  { zh: "」岑娶遂妻公主。", literal: "\" Cen married and thereupon took the princess as wife.", idiomatic: "\" Cen married and thereupon took the princess as wife." },
  { zh: "昆莫死，岑娶代立，為昆彌。", literal: "Kunmo died; Cen married succeeded and was established as Kunmi.", idiomatic: "Kunmo died; Cen married succeeded and was established as Kunmi." },
  { zh: "是時，漢使西逾蔥嶺，抵安息。", literal: "At this time Han envoys west crossed the Onion Mountains and reached Parthia.", idiomatic: "At this time Han envoys west crossed the Onion Mountains and reached Parthia." },
  { zh: "安息發使，以大鳥卵及黎軒善眩人獻於漢，及諸小國驩潛、大益、車姑師、扜冞、蘇䪥之屬，皆隨漢使獻見天子，天子大悅。", literal: "Parthia sent envoys presenting to Han great bird eggs and Lixuan men skilled in illusion; and various small states Huanqian, Dayi, Chegushi, Yuanchen, Suxie, and the like all followed Han envoys to present themselves before the Son of Heaven; the Son of Heaven was greatly pleased.", idiomatic: "Parthia sent envoys presenting to Han ostrich eggs and Lixuan men skilled in illusion; and various small states Huanqian, Dayi, Chegushi, Yuanchen, Suxie, and the like all followed Han envoys to present themselves before the emperor; the emperor was greatly pleased." },
  { zh: "西國使更來更去，天子每巡狩海上，悉從外國客，大都、多人則過之，散財帛以賞賜，厚具以饒給之，以覽示漢富厚焉。", literal: "Western states' envoys came and went repeatedly; whenever the Son of Heaven toured the seacoast he took all foreign guests along; where states were great and populous he passed them by; he scattered wealth and silks to reward and lavishly supplied them, to display Han's wealth and abundance.", idiomatic: "Western states' envoys came and went repeatedly; whenever the emperor toured the seacoast he took all foreign guests along; where states were great and populous he passed them by; he scattered wealth and silks to reward and lavishly supplied them, to display Han's wealth and abundance." },
  { zh: "大角抵，出奇戲、諸怪物，多聚觀者。", literal: "Great wrestling contests were held, producing strange performances and various marvels; many gathered to watch.", idiomatic: "Great wrestling contests were held, producing strange performances and various marvels; many gathered to watch." },
  { zh: "行賞賜，酒池肉林，令外國客遍觀名倉庫府藏之積，見漢之廣大，傾駭之。", literal: "He carried out rewards and gifts, wine pools and meat forests, and ordered foreign guests to view throughout the famous storehouses and treasury accumulations; seeing Han's vastness, they were utterly astonished.", idiomatic: "He carried out rewards and gifts, wine pools and meat forests, and ordered foreign guests to view throughout the famous storehouses and treasury accumulations; seeing Han's vastness, they were utterly astonished." },
  { zh: "大宛左右多蒲萄，可以為酒；", literal: "Around Dayuan there was much grape, which could be made into wine;", idiomatic: "Around Dayuan there was much grape, which could be made into wine;" },
  { zh: "多苜蓿，天馬嗜之；", literal: "much alfalfa, which Heavenly Horses loved;", idiomatic: "much alfalfa, which Heavenly Horses loved;" },
  { zh: "漢使采其實以來，天子種之於離宮別觀旁，極望。", literal: "Han envoys gathered their fruit and brought them; the Son of Heaven planted them beside detached palaces and lodges, as far as the eye could see.", idiomatic: "Han envoys gathered their fruit and brought them; the emperor planted them beside detached palaces and lodges, as far as the eye could see." },
  { zh: "然西域以近匈奴，常畏匈奴使，待之過於漢使焉。", literal: "Yet the Western Regions, being near the Xiongnu, constantly feared Xiongnu envoys and treated them above Han envoys.", idiomatic: "Yet the Western Regions, being near the Xiongnu, constantly feared Xiongnu envoys and treated them above Han envoys." },
  { zh: "----7是歲，匈奴烏維單于死，子烏師廬立，年少，號「兒單于」。", literal: "----7 That year the Xiongnu Chanyu Wuwu died; his son Wushilu was established, young in years, titled \"Child Chanyu.\"", idiomatic: "----7 That year the Xiongnu Chanyu Wuwu died; his son Wushilu was established, young in years, titled \"Child Chanyu.\"" },
  { zh: "自此之後，單于益西北徙，左方兵直雲中，右方直酒泉、敦煌郡。", literal: "From this onward the Chanyu moved ever further northwest; the left-wing troops faced straight on Yunzhong, the right-wing straight on Jiuquan and Dunhuang commanderies.", idiomatic: "From this onward the Chanyu moved ever further northwest; the left-wing troops faced Yunzhong, the right-wing Jiuquan and Dunhuang commanderies." },
  { zh: "1冬，十月，上行幸泰山。", literal: "1 In winter, the tenth month, the emperor traveled in favor to Mount Tai.", idiomatic: "1 In winter, the tenth month, the emperor traveled in favor to Mount Tai." },
  { zh: "十一月，甲子朔旦，冬至，祠上帝於明堂。", literal: "In the eleventh month, on the first day jiazi at dawn at the winter solstice, he sacrificed to the Supreme Lord in the Bright Hall.", idiomatic: "In the eleventh month, on the first day jiazi at dawn at the winter solstice, he sacrificed to the Supreme Lord in the Bright Hall." },
  { zh: "東至海上，考入海及方士求神者莫驗；", literal: "East to the seacoast, he examined those who entered the sea and method masters seeking spirits—none were verified;", idiomatic: "East to the seacoast, he examined those who entered the sea and method masters seeking spirits—none were verified;" },
  { zh: "然益遣，冀遇之。", literal: "yet he sent more, hoping to encounter them.", idiomatic: "yet he sent more, hoping to encounter them." },
  { zh: "----2乙酉，柏梁台災。", literal: "----2 On yiyou, the Boliang Terrace burned.", idiomatic: "----2 On yiyou, the Boliang Terrace burned." },
  { zh: "----3十二月，甲午朔，上親禪-{高里}-，祠-{后土}-，臨勃海，將以望祀蓬萊之屬，冀至殊廷焉。", literal: "----3 In the twelfth month, on the first day jiawu, the emperor personally performed the -{高里}- feng, sacrificed to -{后土}-, approached the Bohai Sea, and was about to gaze and sacrifice to Penglai and the like, hoping to reach the extraordinary court.", idiomatic: "----3 In the twelfth month, on the first day jiawu, the emperor personally performed the -{高里}- feng, sacrificed to -{后土}-, approached the Bohai Sea, and was about to gaze and sacrifice to Penglai and the like, hoping to reach the extraordinary court." },
  { zh: "春，上還，以柏梁災，故朝諸侯，受計於甘泉。", literal: "In spring the emperor returned; because of the Boliang disaster, he therefore received the feudal lords in audience and received accounts at Ganquan.", idiomatic: "In spring the emperor returned; because of the Boliang disaster, he therefore received the feudal lords in audience and received accounts at Ganquan." },
  { zh: "甘泉作諸侯邸。", literal: "At Ganquan residences for the feudal lords were built.", idiomatic: "At Ganquan residences for the feudal lords were built." },
  { zh: "越人勇之曰：「越俗，有火災復起屋，必以大，用勝服之。", literal: "Yong Zhi of Yue said: \"Yue custom: when there is a fire disaster and one rebuilds a house, it must be larger, using size to overcome and subdue it.", idiomatic: "Yong Zhi of Yue said, \"Yue custom: when there is a fire disaster and one rebuilds a house, it must be larger, using size to overcome and subdue it." },
  { zh: "」於是作建章宮，度為千門萬戶。", literal: "\" Thereupon Jianzhang Palace was built, measured at a thousand gates and ten thousand households.", idiomatic: "\" Thereupon Jianzhang Palace was built, measured at a thousand gates and ten thousand households." },
  { zh: "其東則鳳闕，高二十餘丈；", literal: "To its east was Phoenix Tower, more than twenty zhang high;", idiomatic: "To its east was Phoenix Tower, more than twenty zhang high;" },
  { zh: "其西則唐中，數十里虎圈；", literal: "to its west Tangzhong, with a tiger park several tens of li;", idiomatic: "to its west Tangzhong, with a tiger park several tens of li;" },
  { zh: "其北治大池，漸台高二十餘丈，命曰太液池，中有蓬萊、方丈、瀛洲、壺梁，象海中神山、龜魚之屬；", literal: "to its north a great pool was made; the Gradual Terrace was more than twenty zhang high, named Grand Liquid Pool, with within it Penglai, Fangzhang, Yingzhou, and Huliang, representing sea divine mountains, turtles, fish, and the like;", idiomatic: "to its north a great pool was made; the Gradual Terrace was more than twenty zhang high, named Grand Liquid Pool, with within it Penglai, Fangzhang, Yingzhou, and Huliang, representing sea divine mountains, turtles, fish, and the like;" },
  { zh: "其南有玉堂、璧門、大鳥之屬。", literal: "to its south were Jade Hall, Jade Gate, Great Bird, and the like.", idiomatic: "to its south were Jade Hall, Jade Gate, Great Bird, and the like." },
  { zh: "立神明台、井幹樓，度五十丈，輦道相屬焉。", literal: "Spirit Bright Terrace and Well Canopy Tower were erected, measuring fifty zhang, with imperial carriage roads linking one to another.", idiomatic: "Spirit Bright Terrace and Well Canopy Tower were erected, measuring fifty zhang, with imperial carriage roads linking one to another." },
  { zh: "----4大中大夫公孫卿、壺遂、太史令司馬遷等言：「曆紀壞廢，宜改正朔。", literal: "----4 Grand Master Gongsun Qing, Hu Sui, Grand Astrologer Sima Qian, and others said: \"The calendar's records are ruined and abolished; the era name and first month should be corrected.", idiomatic: "----4 Grand Master Gongsun Qing, Hu Sui, Grand Astrologer Sima Qian, and others said, \"The calendar's records are ruined and abolished; the era name and first month should be corrected." },
  { zh: "」上詔兒寬與博士賜等共議，以為宜用夏正。", literal: "\" The emperor ordered Er Kuan together with Academician Ci and others to deliberate jointly; they considered that the Xia first month should be used.", idiomatic: "\" The emperor ordered Er Kuan together with Academician Ci and others to deliberate jointly; they considered that the Xia first month should be used." },
  { zh: "夏，五月，詔卿、遂、遷等共造漢《太初曆》，以正月為歲首，色上黃，數用五，定官名，協音律，定宗廟百官之儀，以為典常，垂之後世-{云}-。", literal: "In summer, the fifth month, Qing, Sui, Qian, and others were ordered jointly to compose Han's Taichu Calendar, taking the first month as year start, color exalting yellow, numbers using five, fixing official titles, harmonizing pitch pipes, fixing the rites of the ancestral temple and the hundred offices, taking these as canonical constants to hand down to later generations -{云}-.", idiomatic: "In summer, the fifth month, Qing, Sui, Qian, and others were ordered jointly to compose Han's Taichu Calendar, taking the first month as year start, exalting the color yellow, using the number five, fixing official titles, harmonizing pitch pipes, fixing the rites of the ancestral temple and the hundred offices, taking these as canonical constants to hand down to later generations -{云}-." },
  { zh: "----5匈奴兒單于好殺伐，國人不安；", literal: "----5 The Xiongnu Child Chanyu loved killing and campaigning; the people of the state were uneasy;", idiomatic: "----5 The Xiongnu Child Chanyu loved killing and campaigning; the people of the state were uneasy;" },
  { zh: "又有天災，畜多死。", literal: "there was also a heaven-sent disaster; livestock mostly died.", idiomatic: "there was also a heaven-sent disaster; livestock mostly died." },
  { zh: "左大都尉使人間告漢曰：「我欲殺單于降漢，漢遠，即兵來迎我，我即發。", literal: "The Left Grand Commandant sent a man secretly to inform Han: \"I wish to kill the Chanyu and surrender to Han; Han is far—if troops come at once to welcome me, I will rise.", idiomatic: "The Left Grand Commandant sent a man secretly to inform Han, saying, \"I wish to kill the Chanyu and surrender to Han; Han is far—if troops come at once to welcome me, I will rise." },
  { zh: "」上乃遣因杅將軍公孫敖築塞外受降城以應之。", literal: "\" The emperor thereupon dispatched General Yinyu Gongsun Ao to build the Surrender-Receiving City outside the passes to respond.", idiomatic: "\" The emperor thereupon dispatched General Yinyu Gongsun Ao to build the Surrender-Receiving City outside the passes to respond." },
  { zh: "----6秋，八月，上行幸安定。", literal: "----6 In autumn, the eighth month, the emperor traveled in favor to Anding.", idiomatic: "----6 In autumn, the eighth month, the emperor traveled in favor to Anding." },
  { zh: "----7漢使入西域者言：「宛有善馬，在貳師城，匿不肯與漢使。", literal: "----7 Han envoys who had entered the Western Regions said: \"Yuan has fine horses at Ershi City; they hide them and refuse to give them to Han envoys.", idiomatic: "----7 Han envoys who had entered the Western Regions said, \"Yuan has fine horses at Ershi City; they hide them and refuse to give them to Han envoys." },
  { zh: "」天子使壯士車令等持千金及金馬以請之。", literal: "\" The Son of Heaven sent stalwarts Che Ling and others bearing a thousand in gold and a golden horse to request them.", idiomatic: "\" The emperor sent stalwarts Che Ling and others bearing a thousand in gold and a golden horse to request them." },
  { zh: "宛王與其群臣謀曰：「漢去我遠，而鹽水中數敗，出其北有胡寇，出其南乏水草，又且往往而絕邑，乏食者多，漢使數百人為輩來，而常乏食，死者過半，是安能致大軍乎！", literal: "The King of Dayuan consulted with his ministers, saying: \"Han is far from us, and in the Saltwater region they are repeatedly defeated; going out to the north there are Hu raiders; going out to the south there is lack of water and grass; moreover along the way towns are often cut off, and many lack food. Han envoys come in parties of several hundred, yet often lack food—more than half die. How could they possibly bring a great army!", idiomatic: "The King of Dayuan consulted with his ministers, saying, \"Han is far from us, and in the Saltwater region they are repeatedly defeated; going out to the north there are Hu raiders; going out to the south there is lack of water and grass; moreover along the way towns are often cut off, and many lack food. Han envoys come in parties of several hundred, yet often lack food—more than half die. How could they possibly bring a great army!\"" },
  { zh: "無奈我何。", literal: "They can do nothing to us.", idiomatic: "They can do nothing to us." },
  { zh: "貳師馬，宛寶馬也。", literal: "Ershi horses are Dayuan's prized horses.", idiomatic: "Ershi horses are Dayuan's prized horses." },
  { zh: "」遂不肯予漢使。", literal: "\" Thereupon they refused to give them to Han envoys.", idiomatic: "\" Thereupon they refused to give them to Han envoys." },
  { zh: "漢使怒，妄言，椎金馬而去。", literal: "The Han envoy was angry, spoke recklessly, smashed the golden horse, and departed.", idiomatic: "The Han envoy was angry, spoke recklessly, smashed the golden horse, and departed." },
  { zh: "宛貴人怒曰：「漢使至輕我！", literal: "A noble of Dayuan said angrily: \"The Han envoy has come to the utmost to slight us!", idiomatic: "A noble of Dayuan said angrily, \"The Han envoy has come to the utmost to slight us!" },
  { zh: "」遣漢使去，令其東邊郁成王遮攻，殺漢使，取其財物。", literal: "\" They sent the Han envoy away, ordered the King of Yucheng on the eastern border to intercept and attack, killed the Han envoy, and seized his goods.", idiomatic: "\" They sent the Han envoy away, ordered the King of Yucheng on the eastern border to intercept and attack, killed the Han envoy, and seized his goods." },
  { zh: "於是天子大怒。", literal: "Thereupon the Son of Heaven was greatly angry.", idiomatic: "Thereupon the Son of Heaven was greatly angry." },
  { zh: "諸嘗使宛姚定漢等言：「宛兵弱，誠以漢兵不過三千人，強弩射之，可盡虜矣。", literal: "Those who had previously been envoys to Dayuan, Yao Dinghan and others, said: \"Dayuan's troops are weak; truly if Han troops do not exceed three thousand, shooting them with strong crossbows, one could capture them all.", idiomatic: "Those who had previously been envoys to Dayuan, Yao Dinghan and others, said, \"Dayuan's troops are weak; truly if Han troops do not exceed three thousand, shooting them with strong crossbows, one could capture them all.\"" },
  { zh: "」天子嘗使浞野侯以七百騎虜樓蘭王，以定漢等言為然；", literal: "\" The Son of Heaven had once sent the Marquis of Zhuoye with seven hundred horsemen to capture the King of Kroraina, and took Yao Dinghan and others' words as true;", idiomatic: "\" The Son of Heaven had once sent the Marquis of Zhuoye with seven hundred horsemen to capture the King of Kroraina, and took Yao Dinghan and others' words as true;" },
  { zh: "而欲侯寵姬李氏，乃拜李夫人兄廣利為貳師將軍，發屬國六千騎及郡國惡少年數萬人，以往伐宛。", literal: "yet wishing to enfeoff the favored lady of the Li clan, he then appointed Lady Li's elder brother Guangli as General of the Ershi, raised six thousand horsemen of dependent states and tens of thousands of vicious youths from commanderies and kingdoms, and sent them to attack Dayuan.", idiomatic: "yet wishing to enfeoff the favored lady of the Li clan, he then appointed Lady Li's elder brother Guangli as General of the Ershi, raised six thousand horsemen of dependent states and tens of thousands of vicious youths from commanderies and kingdoms, and sent them to attack Dayuan." },
  { zh: "期至貳師城取善馬，故號貳師將軍。", literal: "They expected to reach Ershi city and obtain good horses—hence the title General of the Ershi.", idiomatic: "They expected to reach Ershi city and obtain good horses—hence the title General of the Ershi." },
  { zh: "趙始成為軍正，故浩侯王恢使導軍，而李哆為校尉，制軍事。", literal: "Zhao Shicheng was army inspector; the former Marquis of Hao Wang Hui was sent to guide the army; Li Duo was colonel overseeing military affairs.", idiomatic: "Zhao Shicheng was army inspector; the former Marquis of Hao Wang Hui was sent to guide the army; Li Duo was colonel overseeing military affairs." },
  { zh: ":臣光曰：武帝欲侯寵姬李氏，而使廣利將兵伐宛，其意以為非有功不侯，不欲負高帝之約也。", literal: ": Your subject Guang says: Emperor Wu wished to enfeoff the favored lady of the Li clan, and therefore had Guangli lead troops to attack Dayuan; his intent was that without merit there should be no enfeoffment—he did not wish to violate High Emperor's covenant.", idiomatic: ": Your subject Guang says: Emperor Wu wished to enfeoff the favored lady of the Li clan, and therefore had Guangli lead troops to attack Dayuan; his intent was that without merit there should be no enfeoffment—he did not wish to violate High Emperor's covenant." },
  { zh: "夫軍旅大事，國之安危、民之死生系焉。", literal: "Military affairs are a great matter—on them depend the state's safety and danger, the people's life and death.", idiomatic: "Military affairs are a great matter—on them depend the state's safety and danger, the people's life and death." },
  { zh: "苟為不擇賢愚而授之，欲徼幸咫尺之功，藉以為名而私其所愛，不若無功而侯之為愈也。", literal: "If one does not choose between worthy and foolish in conferring command, wishing for success within a foot's span and using that as a title to favor whom one loves privately, that is not as good as enfeoffing without merit.", idiomatic: "If one does not choose between worthy and foolish in conferring command, wishing for success within a foot's span and using that as a title to favor whom one loves privately, that is not as good as enfeoffing without merit." },
  { zh: "然則武帝有見於封國，無見於置將；", literal: "Thus Emperor Wu had insight regarding enfeoffment of states but none regarding appointment of generals;", idiomatic: "Thus Emperor Wu had insight regarding enfeoffment of states but none regarding appointment of generals;" },
  { zh: "謂之能守先帝之約，臣曰過矣。", literal: "to call this upholding the former emperor's covenant—your subject says it is excessive.", idiomatic: "to call this upholding the former emperor's covenant—your subject says it is excessive." },
  { zh: "----8中尉王溫舒坐為奸利，罪當族，自殺；", literal: "----8 Commandant Wang Wenshu, guilty of corrupt profit-taking, offense warranting execution of the clan, killed himself;", idiomatic: "----8 Commandant Wang Wenshu, guilty of corrupt profit-taking, offense warranting execution of the clan, killed himself;" },
  { zh: "時兩弟及兩婚家亦各自坐佗罪而族。", literal: "at the time his two younger brothers and two families by marriage each were guilty of other offenses and the clan was executed.", idiomatic: "at the time his two younger brothers and two families by marriage each were guilty of other offenses and the clan was executed." },
  { zh: "光祿勳徐自為曰：「悲夫！", literal: "Palace Attendant Xu Ziwei said: \"Alas!", idiomatic: "Palace Attendant Xu Ziwei said, \"Alas!" },
  { zh: "古有三族，而王溫舒罪至同時而五族乎！", literal: "Anciently there was execution of three clans, yet Wang Wenshu's offense reached five clans at once!", idiomatic: "Anciently there was execution of three clans, yet Wang Wenshu's offense reached five clans at once!" },
  { zh: "」----9關東蝗大起，飛西至敦煌。", literal: "\" ----9 Locusts rose greatly in Guandong, flying west as far as Dunhuang.", idiomatic: "\" ----9 Locusts rose greatly in Guandong, flying west as far as Dunhuang." },
  { zh: "1春，正月，戊申，牧丘恬侯石慶薨。", literal: "1 In spring, the first month, on wushen, Marquis of Muqiu Lord Shi Qing died.", idiomatic: "1 In spring, the first month, on wushen, Marquis of Muqiu Lord Shi Qing died." },
  { zh: "----2閏月，丁丑，以太僕公孫賀為丞相，封葛繹侯。", literal: "----2 In the intercalary month, on dingchou, Grand Coachman Gongsun He was made Chancellor and enfeoffed as Marquis of Geyi.", idiomatic: "----2 In the intercalary month, on dingchou, Grand Coachman Gongsun He was appointed Chancellor and enfeoffed as Marquis of Geyi." },
  { zh: "時朝廷多事，督責大臣，自公孫弘後，丞相比坐事死。", literal: "At this time the court had many affairs and pressed senior officials; since Gongsun Hong, chancellors in succession died for their offenses.", idiomatic: "At this time the court had many affairs and pressed senior officials; since Gongsun Hong, chancellors in succession died for their offenses." },
  { zh: "石慶雖以謹得終，然數被譴。", literal: "Shi Qing, though by caution reached his end, was repeatedly rebuked.", idiomatic: "Shi Qing, though by caution he reached his end, was repeatedly rebuked." },
  { zh: "賀引拜為丞相，不受印綬，頓首涕泣不肯起。", literal: "When He was led in to be appointed Chancellor, he would not accept seal and ribbon, kowtowed weeping and refused to rise.", idiomatic: "When He was led in to be appointed Chancellor, he would not accept seal and ribbon, kowtowed weeping and refused to rise." },
  { zh: "上乃起去，賀不得已，拜，出曰：「我從是殆矣！", literal: "The emperor then rose and left; He had no choice but to bow; going out he said: \"From this I am nearly done for!", idiomatic: "The emperor then rose and left; He had no choice but to bow; going out he said, \"From this I am nearly done for!" },
  { zh: "」----3三月，上行幸河東，祠-{后土}-。", literal: "\" ----3 In the third month the emperor traveled in person to Hedong and sacrificed to -{Houtu}-.", idiomatic: "\" ----3 In the third month the emperor traveled in person to Hedong and sacrificed to -{Houtu}-." },
  { zh: "----4夏，五月，籍吏民馬補車騎馬。", literal: "----4 In summer, the fifth month, officials' and commoners' horses were registered to supplement chariot and cavalry horses.", idiomatic: "----4 In summer, the fifth month, officials' and commoners' horses were registered to supplement chariot and cavalry horses." },
  { zh: "----5秋，蝗。", literal: "----5 In autumn, locusts.", idiomatic: "----5 In autumn, there were locusts." },
  { zh: "----6貳師將軍之西也，既過鹽水，當道小國各城守，不肯給食，攻之不能下。", literal: "----6 When the General of the Ershi marched west, having passed the Saltwater region, each small state on the route walled and held, refused to supply food, and though attacked could not be taken.", idiomatic: "----6 When the General of the Ershi marched west, having passed the Saltwater region, each small state on the route walled and held, refused to supply food, and though attacked could not be taken." },
  { zh: "下者得食，不下者數日則去。", literal: "Where they took them they obtained food; where they did not, after several days they departed.", idiomatic: "Where they took them they obtained food; where they did not, after several days they departed." },
  { zh: "比至郁成，士至者不過數千，皆饑罷。", literal: "By the time they reached Yucheng, soldiers who had arrived were no more than several thousand, all hungry and exhausted.", idiomatic: "By the time they reached Yucheng, soldiers who had arrived were no more than several thousand, all hungry and exhausted." },
  { zh: "攻郁成，郁成大破之，所殺傷甚眾。", literal: "They attacked Yucheng; Yucheng greatly defeated them, and those killed and wounded were very many.", idiomatic: "They attacked Yucheng; Yucheng greatly defeated them, and those killed and wounded were very many." },
  { zh: "貳師將軍與李哆、趙始成等計：「至郁成尚不能舉，況至其王都乎！", literal: "The General of the Ershi with Li Duo, Zhao Shicheng, and others deliberated: \"At Yucheng we still could not take it—how much less reach their royal capital!", idiomatic: "The General of the Ershi with Li Duo, Zhao Shicheng, and others deliberated, \"At Yucheng we still could not take it—how much less reach their royal capital!" },
  { zh: "」引兵而還。", literal: "\" They led the army back.", idiomatic: "\" They led the army back." },
  { zh: "至敦煌，士不過什一二，使使上書言：「道遠乏食，且士卒不患戰而患饑，人少，不足以拔宛。", literal: "Reaching Dunhuang, soldiers were no more than one or two in ten; they sent envoys to memorialize, saying: \"The road is far and food scarce; moreover the troops do not fear battle but fear hunger; our numbers are few—not enough to storm Dayuan.", idiomatic: "Reaching Dunhuang, soldiers were no more than one or two in ten; they sent envoys to memorialize, saying, \"The road is far and food scarce; moreover the troops do not fear battle but fear hunger; our numbers are few—not enough to storm Dayuan." },
  { zh: "願且罷兵，益發而復往。", literal: "We wish for the moment to halt the army, raise more troops, and go again.", idiomatic: "We wish for the moment to halt the army, raise more troops, and go again." },
  { zh: "」天子聞之，大怒，使使遮玉門曰：「軍有敢入者，輒斬之！", literal: "\" The Son of Heaven heard it and was greatly angry; he sent envoys to block Yumen Pass, saying: \"If any in the army dare enter, execute them at once!", idiomatic: "\" The Son of Heaven heard it and was greatly angry; he sent envoys to block Yumen Pass, saying, \"If any in the army dare enter, execute them at once!" },
  { zh: "」貳師恐，因留敦煌。", literal: "\" The Ershi was afraid and therefore remained at Dunhuang.", idiomatic: "\" The Ershi was afraid and therefore remained at Dunhuang." },
  { zh: "----7上猶以受降城去匈奴遠，遣浚稽將軍趙破奴將二萬餘騎出朔方西北二千餘里，期至浚稽山而還。", literal: "----7 The emperor still thought Shoujiang city was far from the Xiongnu; he dispatched General of Junji Zhao Ponu leading more than twenty thousand horsemen out from northwest of Shuofang over two thousand li, expecting to reach Mount Junji and return.", idiomatic: "----7 The emperor still thought Shoujiang city was far from the Xiongnu; he dispatched General of Junji Zhao Ponu leading more than twenty thousand horsemen out from northwest of Shuofang over two thousand li, expecting to reach Mount Junji and return." },
  { zh: "浞野侯既至期，左大都尉欲發而覺，單于誅之，發左方兵擊浞野侯。", literal: "When the Marquis of Zhuoye had reached the appointed time, the Grand Commandant of the Left wished to rise but was discovered; the Chanyu executed him and raised troops of the Left to strike the Marquis of Zhuoye.", idiomatic: "When the Marquis of Zhuoye had reached the appointed time, the Grand Commandant of the Left wished to rise but was discovered; the Chanyu executed him and raised troops of the Left to strike the Marquis of Zhuoye." },
  { zh: "浞野侯行捕首虜，得數千人，還，未至受降城四百里，匈奴兵八萬騎圍之。", literal: "The Marquis of Zhuoye on the march captured heads and captives, obtaining several thousand; returning, not yet four hundred li from Shoujiang city, eighty thousand Xiongnu horsemen surrounded him.", idiomatic: "The Marquis of Zhuoye on the march captured heads and captives, obtaining several thousand; returning, not yet four hundred li from Shoujiang city, eighty thousand Xiongnu horsemen surrounded him." },
  { zh: "浞野侯夜自出求水，匈奴間捕生得浞野侯，因急擊其軍，軍吏畏亡將而誅，莫相勸歸者，軍遂沒於匈奴。", literal: "The Marquis of Zhuoye by night went out himself to seek water; Xiongnu scouts captured the Marquis of Zhuoye alive; they then pressed the attack on his army; army officers feared that with the general lost they would be executed, and none urged one another to return—the army was thereupon lost to the Xiongnu.", idiomatic: "The Marquis of Zhuoye by night went out himself to seek water; Xiongnu scouts captured the Marquis of Zhuoye alive; they then pressed the attack on his army; army officers feared that with the general lost they would be executed, and none urged one another to return—the army was thereupon lost to the Xiongnu." },
  { zh: "兒單于大喜，因遣奇兵攻受降城，不能下，乃寇入邊而去。", literal: "The Child Chanyu was greatly pleased and thereupon sent picked troops to attack Shoujiang city; they could not take it, and then raided into the border and departed.", idiomatic: "The Child Chanyu was greatly pleased and thereupon sent picked troops to attack Shoujiang city; they could not take it, and then raided into the border and departed." },
  { zh: "----8冬，十二月，兒寬卒。", literal: "----8 In winter, the twelfth month, Ni Kuan died.", idiomatic: "----8 In winter, the twelfth month, Ni Kuan died." },
  { zh: "1春，正月，膠東太守延廣為御史大夫。", literal: "1 In spring, the first month, Administrator of Jiaodong Yan Guang was made Grand Counsellor.", idiomatic: "1 In spring, the first month, Administrator of Jiaodong Yan Guang was appointed Grand Counsellor." },
  { zh: "----2上東巡海上，考神仙之屬皆無驗，令祠官禮東泰山。", literal: "----2 The emperor toured east along the sea; examining the immortals and their kind, none was verified; he ordered sacrifice officers to perform rites at the Eastern Mount Tai.", idiomatic: "----2 The emperor toured east along the sea; examining the immortals and their kind, none was verified; he ordered sacrifice officers to perform rites at the Eastern Mount Tai." },
  { zh: "夏，四月，還，修封泰山，禪石閭。", literal: "In summer, the fourth month, he returned, repaired the feng at Mount Tai, and performed the shan at Shilü.", idiomatic: "In summer, the fourth month, he returned, repaired the feng at Mount Tai, and performed the shan at Shilü." },
  { zh: "----3匈奴兒單于死，子年少，匈奴立其季父右賢王呴犁湖為單于。", literal: "----3 The Xiongnu Child Chanyu died; his son was young; the Xiongnu established his younger paternal uncle, the Wise King of the Right Hulihu, as Chanyu.", idiomatic: "----3 The Xiongnu Child Chanyu died; his son was young; the Xiongnu established his younger paternal uncle, the Wise King of the Right Hulihu, as Chanyu." },
  { zh: "----4上遣光祿勳徐自為出五原塞數百里，遠者千餘里，築城、障、列亭，西北至廬朐，而使游擊將軍韓說、長平侯衛伉屯其旁；", literal: "----4 The emperor dispatched Palace Attendant Xu Ziwei out from Wuyuan Pass several hundred li, in distant places over a thousand li, to build forts, barriers, and beacon towers in rows, northwest to Lujü, and had General of Rapid Attack Han Yue and Marquis of Changping Wei Kang encamp beside them;", idiomatic: "----4 The emperor dispatched Palace Attendant Xu Ziwei out from Wuyuan Pass several hundred li, in distant places over a thousand li, to build forts, barriers, and beacon towers in rows, northwest to Lujü, and had General of Rapid Attack Han Yue and Marquis of Changping Wei Kang encamp beside them;" },
  { zh: "使強弩都尉路博德築居延澤上。", literal: "he had Chief of Strong Crossbows Luo Bode build on the Juyan marshes.", idiomatic: "he had Chief of Strong Crossbows Luo Bode build on the Juyan marshes." },
  { zh: "秋，匈奴大入定襄、雲中，殺略數千人，敗數二千石而去，行破壞光祿所築城、列亭、障；", literal: "In autumn the Xiongnu entered Dingxiang and Yunzhong in force, killed and plundered several thousand, defeated several officials of two-thousand-bushel rank and departed, and on the march destroyed the forts, beacon towers, and barriers that the Palace Attendant had built;", idiomatic: "In autumn the Xiongnu entered Dingxiang and Yunzhong in force, killed and plundered several thousand, defeated several officials of two-thousand-bushel rank and departed, and on the march destroyed the forts, beacon towers, and barriers that the Palace Attendant had built;" },
  { zh: "又使右賢王入酒泉、張掖，略數千人。", literal: "he also sent the Wise King of the Right into Jiuquan and Zhangye, plundering several thousand.", idiomatic: "he also sent the Wise King of the Right into Jiuquan and Zhangye, plundering several thousand." },
  { zh: "會軍正任文擊救，盡復失所得而去。", literal: "Army inspector Ren Wen met them with a rescue attack and wholly recovered what had been lost before they departed.", idiomatic: "Army inspector Ren Wen met them with a rescue attack and wholly recovered what had been lost before they departed." },
  { zh: "----5是歲，睢陽侯張昌坐為太常乏祠，國除。", literal: "----5 That year, Marquis of Suiyang Zhang Chang, guilty as Grand Minister of Imperial Worship of deficient sacrifice, had his state abolished.", idiomatic: "----5 That year, Marquis of Suiyang Zhang Chang, guilty as Grand Minister of Imperial Worship of deficient sacrifice, had his state abolished." },
  { zh: "初，高祖封功臣為列侯百四十有三人。", literal: "At the beginning, Gaozu enfeoffed meritorious ministers as full marquises—one hundred forty-three persons.", idiomatic: "At the beginning, Gaozu enfeoffed meritorious ministers as full marquises—one hundred forty-three persons." },
  { zh: "時兵革之餘，大城、名都民人散亡，戶口可得而數，裁什二三。", literal: "At that time, in the aftermath of arms, in great cities and famous capitals the people were scattered and lost; households that could be counted were barely two or three in ten.", idiomatic: "At that time, in the aftermath of arms, in great cities and famous capitals the people were scattered and lost; households that could be counted were barely two or three in ten." },
  { zh: "大侯不過萬家，小者五六百戶。", literal: "Great marquisates had no more than ten thousand households; small ones five or six hundred.", idiomatic: "Great marquisates had no more than ten thousand households; small ones five or six hundred." },
  { zh: "其封爵之誓曰：「使黃河如帶，泰山若厲，國以永存，爰及苗裔。", literal: "The oath of their enfeoffment said: \"Though the Yellow River become a belt, Mount Tai a whetstone, the state shall endure forever, extending to descendants.", idiomatic: "The oath of their enfeoffment said, \"Though the Yellow River become a belt, Mount Tai a whetstone, the state shall endure forever, extending to descendants." },
  { zh: "」申以丹書之信，重以白馬之盟。", literal: "\" It was affirmed with the red-lettered pledge and sealed again with the white-horse covenant.", idiomatic: "\" It was affirmed with the red-lettered pledge and sealed again with the white-horse covenant." },
  { zh: "及-{高后}-時，盡差第列侯位次，藏諸宗廟，副在有司。", literal: "By the time of -{Empress Gao}-, the ranks of full marquises were wholly ordered by degree, stored in the ancestral temple, with copies in the responsible offices.", idiomatic: "By the time of -{Empress Gao}-, the ranks of full marquises were wholly ordered by degree, stored in the ancestral temple, with copies in the responsible offices." },
  { zh: "逮文、景，四五世間，流民既歸，戶口亦息，列侯大者至三四萬戶，小國自倍，富厚如之。", literal: "Reaching Wen and Jing, within four or five generations the floating population had returned, households had also revived; great full marquisates reached thirty or forty thousand households, small states doubled themselves—wealth and thickness like this.", idiomatic: "Reaching Wen and Jing, within four or five generations the floating population had returned, households had also revived; great full marquisates reached thirty or forty thousand households, small states doubled themselves—wealth and thickness like this." },
  { zh: "子孫驕逸，多抵法禁，隕身失國，至是見侯裁四人，罔亦少密焉。", literal: "Descendants grew arrogant and dissolute, many ran afoul of law and prohibition, lost their persons and forfeited their states; by now visible marquises were barely four persons, and few remained in close succession.", idiomatic: "Descendants grew arrogant and dissolute, many ran afoul of law and prohibition, lost their persons and forfeited their states; by now visible marquises were barely four persons, and few remained in close succession." },
  { zh: "----6漢既亡浞野之兵，公卿議者皆願罷宛軍，專力攻胡。", literal: "----6 Han having lost the army of Zhuoye, those among the high ministers who deliberated all wished to halt the Dayuan army and concentrate strength on attacking the Hu.", idiomatic: "----6 Han having lost the army of Zhuoye, those among the high ministers who deliberated all wished to halt the Dayuan army and concentrate strength on attacking the Hu." },
  { zh: "天子業出兵誅宛，宛小國而不能下，則大夏之屬漸輕漢，而宛善馬絕不來，烏孫、輪台易苦漢使，為外國笑，乃案言伐宛尤不便者鄧光等。", literal: "The Son of Heaven had already raised troops to punish Dayuan; if a small state like Dayuan could not be taken, then the Da Yuezhi and their kind would gradually slight Han, Dayuan's good horses would never come, Wusun and Luntai would readily distress Han envoys, and foreign states would laugh—thereupon he prosecuted Deng Guang and others who had said attacking Dayuan was especially inconvenient.", idiomatic: "The Son of Heaven had already raised troops to punish Dayuan; if a small state like Dayuan could not be taken, then the Da Yuezhi and their kind would gradually slight Han, Dayuan's good horses would never come, Wusun and Luntai would readily distress Han envoys, and foreign states would laugh—thereupon he prosecuted Deng Guang and others who had said attacking Dayuan was especially inconvenient." },
  { zh: "赦囚徒，發惡少年及邊騎，歲餘而出敦煌者六萬人，負私從者不與，牛十萬，馬三萬匹，驢、橐駝以萬數，繼糧、兵弩甚設。", literal: "He pardoned convicts, raised vicious youths and border horsemen; after more than a year those who went out from Dunhuang were sixty thousand; private followers who bore their own supplies were not counted; cattle one hundred thousand, horses thirty thousand, donkeys and Bactrian camels by the tens of thousands; relay grain and weapons and crossbows were abundantly provided.", idiomatic: "He pardoned convicts and raised vicious youths and border horsemen; after more than a year those who went out from Dunhuang were sixty thousand; private followers who bore their own supplies were not counted; cattle one hundred thousand, horses thirty thousand, donkeys and Bactrian camels by the tens of thousands; relay grain and weapons and crossbows were abundantly provided." },
  { zh: "天下騷動，轉相奉伐宛五十餘校尉。", literal: "All under Heaven was in turmoil; relays supplied one another for the attack on Dayuan—over fifty colonels.", idiomatic: "All under Heaven was in turmoil; relays supplied one another for the attack on Dayuan—over fifty colonels." },
  { zh: "宛城中無井，汲城外流水，於是遣水工徙其城下水，空以穴其城。", literal: "Within Dayuan city there were no wells; they drew flowing water outside the walls; thereupon he sent water engineers to divert the water below the city and tunnel into the city.", idiomatic: "Within Dayuan city there were no wells; they drew flowing water outside the walls; thereupon he sent water engineers to divert the water below the city and tunnel into the city." },
  { zh: "益發戍甲卒十八萬酒泉、張掖北，置居延、休屠屯兵以衛酒泉，而發天下吏有罪者、亡命者及贅婿、賈人、故有市籍、父母大父母有市籍者凡七科，適為兵；", literal: "He further raised one hundred eighty thousand garrison armor-clad troops north of Jiuquan and Zhangye, stationed troops at Juyan and Xiutu to guard Jiuquan, and raised from all under Heaven officials guilty of offenses, fugitives, sons-in-law living with wives' families, merchants, those formerly on market registers, and those whose parents or great-grandparents had market registers—in all seven categories—assigning them as soldiers;", idiomatic: "He further raised one hundred eighty thousand garrison armor-clad troops north of Jiuquan and Zhangye, stationed troops at Juyan and Xiutu to guard Jiuquan, and raised from all under Heaven officials guilty of offenses, fugitives, sons-in-law living with wives' families, merchants, those formerly on market registers, and those whose parents or great-grandparents had market registers—in all seven categories—assigning them as soldiers;" },
  { zh: "及載糒給貳師，轉車人徒相連屬；", literal: "and those who carried grain to supply the Ershi—cart men and porters linked in continuous files;", idiomatic: "and those who carried grain to supply the Ershi—cart men and porters linked in continuous files;" },
  { zh: "而拜習馬者二人為執、驅馬校尉，備破宛擇取其善馬-{云}-。", literal: "he appointed two men skilled in horses as colonels of holding and driving horses, prepared for when Dayuan was broken to select its good horses -{yun}-.", idiomatic: "he appointed two men skilled in horses as colonels of holding and driving horses, prepared for when Dayuan was broken to select its good horses -{yun}-." },
  { zh: "於是貳師後復行，兵多，所至小國莫不迎，出食給軍。", literal: "Thereupon the Ershi again marched; the army was large; every small state reached did not fail to welcome them and put out food to supply the army.", idiomatic: "Thereupon the Ershi again marched; the army was large; every small state reached did not fail to welcome them and put out food to supply the army." },
  { zh: "至輪台，輪台不下。", literal: "Reaching Luntai, Luntai would not submit.", idiomatic: "Reaching Luntai, Luntai would not submit." },
  { zh: "攻數日，屠之。", literal: "After several days of attack they slaughtered it.", idiomatic: "After several days of attack they slaughtered it." },
  { zh: "自此而西，平行至宛城，兵到者三萬。", literal: "From here west they marched levelly to Dayuan city; troops who arrived were thirty thousand.", idiomatic: "From here west they marched levelly to Dayuan city; troops who arrived were thirty thousand." },
  { zh: "宛兵迎擊漢兵，漢兵射敗之，宛兵走入，保其城。", literal: "Dayuan troops met and struck Han troops; Han troops shot and defeated them; Dayuan troops ran in and held their city.", idiomatic: "Dayuan troops met and struck Han troops; Han troops shot and defeated them; Dayuan troops ran in and held their city." },
  { zh: "貳師欲攻郁成城，恐留行而令宛益生詐，乃先至宛，決其水原移之，則宛固已憂困，圍其城，攻之四十餘日。", literal: "The Ershi wished to attack Yucheng city, fearing that lingering on the march would let Dayuan grow more deceitful; he therefore went first to Dayuan, cut and diverted its water source, so that Dayuan was already anxious and distressed; he besieged the city and attacked over forty days.", idiomatic: "The Ershi wished to attack Yucheng city, fearing that lingering on the march would let Dayuan grow more deceitful; he therefore went first to Dayuan, cut and diverted its water source, so that Dayuan was already anxious and distressed; he besieged the city and attacked for over forty days." },
  { zh: "宛貴人謀曰：「王毋寡匿善馬，殺漢使，今殺王而出善馬，漢兵宜解；", literal: "Dayuan nobles deliberated, saying: \"King Wugua hid good horses and killed Han envoys; now if we kill the king and produce good horses, Han troops should withdraw;", idiomatic: "Dayuan nobles deliberated, saying, \"King Wugua hid good horses and killed Han envoys; now if we kill the king and produce good horses, Han troops should withdraw;" },
  { zh: "即不解，乃力戰而死，未晚也。", literal: "if they do not withdraw, then to fight with full strength and die is not yet late.", idiomatic: "if they do not withdraw, then to fight with full strength and die is not yet late." },
  { zh: "」宛貴人皆以為然，共殺王。", literal: "\" The Dayuan nobles all thought it right and together killed the king.", idiomatic: "\" The Dayuan nobles all thought it right and together killed the king." },
  { zh: "其外城壞，虜宛貴人勇將煎靡。", literal: "The outer city was broken; they captured the Dayuan noble and brave general Jian Mi.", idiomatic: "The outer city was broken; they captured the Dayuan noble and brave general Jian Mi." },
  { zh: "宛大恐，走入城中，持王毋寡頭，遣人使貳師，約曰：「漢無攻我，我盡出善馬恣所取，而給漢軍食。", literal: "Dayuan was greatly afraid, ran into the city, held King Wugua's head, and sent men to the Ershi with terms, saying: \"If Han does not attack us, we will bring out all good horses for you to take at will and supply Han army food.", idiomatic: "Dayuan was greatly afraid, ran into the city, held King Wugua's head, and sent men to the Ershi with terms, saying, \"If Han does not attack us, we will bring out all good horses for you to take at will and supply Han army food." },
  { zh: "即不聽我，我盡殺善馬，康居之救又且至，至，我居內，康居居外，與漢軍戰。", literal: "If you do not heed us, we will kill all good horses; Kangju's rescue is also about to arrive—when it comes, we will hold the interior and Kangju the exterior, and fight Han troops.", idiomatic: "If you do not heed us, we will kill all good horses; Kangju's rescue is also about to arrive—when it comes, we will hold the interior and Kangju the exterior, and fight Han troops." },
  { zh: "孰計之，何從？", literal: "Weigh it—which course will you follow?", idiomatic: "Weigh it—which course will you follow?" },
  { zh: "」是時，康居候視漢兵尚盛，不敢進。", literal: "\" At this time Kangju observed Han troops were still strong and did not dare advance.", idiomatic: "\" At this time Kangju observed Han troops were still strong and did not dare advance." },
  { zh: "貳師聞宛城中新得漢人，知穿井，而其內食尚多，計以為「來誅首惡者毋寡，毋寡頭已至，如此不許則堅守，而康居候漢兵罷來救宛，破漢兵必矣」，乃許宛之約。", literal: "The Ershi heard that in Dayuan city they had newly obtained Han men who knew how to dig wells, and that food within was still plentiful; he reckoned: \"They came to punish the chief culprit Wugua; Wugua's head has arrived—if we do not agree thus they will hold firm, and Kangju will wait until Han troops tire and come to rescue Dayuan; breaking Han troops is certain\"—thereupon he agreed to Dayuan's terms.", idiomatic: "The Ershi heard that in Dayuan city they had newly obtained Han men who knew how to dig wells, and that food within was still plentiful; he reckoned, \"They came to punish the chief culprit Wugua; Wugua's head has arrived—if we do not agree thus they will hold firm, and Kangju will wait until Han troops tire and come to rescue Dayuan; breaking Han troops is certain\"—thereupon he agreed to Dayuan's terms." },
  { zh: "宛乃出其馬，令漢自擇之，而多出食食漢軍。", literal: "Dayuan thereupon brought out its horses, let Han choose for themselves, and put out much food to feed Han troops.", idiomatic: "Dayuan thereupon brought out its horses, let Han choose for themselves, and put out much food to feed Han troops." },
  { zh: "漢軍取其善馬數十匹，中馬以下牝牡三千餘匹，而立宛貴人之故時遇漢善者名昧蔡為宛王，與盟而罷兵。", literal: "Han troops took several tens of good horses and over three thousand ordinary horses below that, male and female; they established the Dayuan noble who in former times had treated Han well, named Mei Cai, as King of Dayuan, made covenant, and halted the army.", idiomatic: "Han troops took several tens of good horses and over three thousand ordinary horses below that, male and female; they established the Dayuan noble who in former times had treated Han well, named Mei Cai, as King of Dayuan, made covenant, and halted the army." },
  { zh: "初，貳師起敦煌西，分為數軍，從南、北道。", literal: "At the beginning, when the Ershi set out west from Dunhuang, he divided into several armies, taking the southern and northern routes.", idiomatic: "At the beginning, when the Ershi set out west from Dunhuang, he divided into several armies, taking the southern and northern routes." },
  { zh: "校尉王申生將千餘人別至郁成，郁成王擊滅之，數人脫亡，走貳師。", literal: "Colonel Wang Shensheng led over a thousand men separately to Yucheng; the King of Yucheng attacked and destroyed them; several men escaped and fled to the Ershi.", idiomatic: "Colonel Wang Shensheng led over a thousand men separately to Yucheng; the King of Yucheng attacked and destroyed them; several men escaped and fled to the Ershi." },
  { zh: "貳師令搜粟都尉上官桀往攻郁成，郁成王亡走康居，桀追至康居。", literal: "The Ershi ordered Chief of Grain Search Shangguan Jie to go attack Yucheng; the King of Yucheng fled to Kangju; Jie pursued to Kangju.", idiomatic: "The Ershi ordered Chief of Grain Search Shangguan Jie to go attack Yucheng; the King of Yucheng fled to Kangju; Jie pursued to Kangju." },
  { zh: "康居聞漢已破宛，出郁成王與桀，桀令四騎士縛守詣貳師。", literal: "Kangju heard Han had already broken Dayuan, produced the King of Yucheng to Jie; Jie ordered four horsemen to bind and guard him and send him to the Ershi.", idiomatic: "Kangju heard Han had already broken Dayuan, produced the King of Yucheng to Jie; Jie ordered four horsemen to bind and guard him and send him to the Ershi." },
  { zh: "上邽騎士趙弟恐失郁成王，拔劍擊斬其首，追及貳師。", literal: "A horseman of Shanggui, Zhao Di, feared losing the King of Yucheng, drew his sword, struck, and beheaded him, and caught up with the Ershi.", idiomatic: "A horseman of Shanggui, Zhao Di, feared losing the King of Yucheng, drew his sword, struck, and beheaded him, and caught up with the Ershi." },
  { zh: "1春，貳師將軍來至京師。", literal: "1 In spring the General of the Ershi came to the capital.", idiomatic: "1 In spring the General of the Ershi came to the capital." },
  { zh: "貳師所過小國聞宛破，皆使其子弟從入貢獻，見天子，因為質焉。", literal: "Small states the Ershi passed heard Dayuan was broken; all sent their sons and younger brothers to follow in tribute and presentation, saw the Son of Heaven, and thereby became hostages.", idiomatic: "Small states the Ershi passed heard Dayuan was broken; all sent their sons and younger brothers to follow in tribute and presentation, saw the Son of Heaven, and thereby became hostages." },
  { zh: "軍還，入馬千餘匹。", literal: "When the army returned, they presented over a thousand horses.", idiomatic: "When the army returned, they presented over a thousand horses." },
  { zh: "後行，軍非乏食，戰死不甚多，而將吏貪，不愛卒，侵牟之，以此物故者眾。", literal: "On the later march the army did not lack food; battle deaths were not very many; yet generals and officers were greedy, did not cherish the soldiers, and extorted them—for this reason deaths were many.", idiomatic: "On the later march the army did not lack food; battle deaths were not very many; yet generals and officers were greedy, did not cherish the soldiers, and extorted them—for this reason deaths were many." },
  { zh: "天子為萬里而伐，不錄其過，乃下詔封李廣利為海西侯，封趙弟為新畤侯，以上官桀為少府，軍官吏為九卿者三人，諸侯相、郡守、二千石百餘人，千石以下千餘人，奮行者官過其望，以謫過行，皆黜其勞，士卒賜直四萬錢。", literal: "The Son of Heaven, having campaigned for ten thousand li, did not record their faults; he thereupon issued an edict enfeoffing Li Guangli as Marquis of Haixi, enfeoffing Zhao Di as Marquis of Xindi, making Shangguan Jie Privy Treasurer, three army officers and clerks as one of the Nine Ministers, more than a hundred feudal lords' chancellors, commandery governors, and two-thousand-bushel officials, more than a thousand below one thousand bushels; those who strove forward received offices surpassing their hopes, while those who went on account of banishment-faults—all had their merit dismissed; soldiers were given four ten-thousand in cash.", idiomatic: "The emperor, having campaigned ten thousand li, did not record their faults; he issued an edict enfeoffing Li Guangli as Marquis of Haixi and Zhao Di as Marquis of Xindi, making Shangguan Jie Privy Treasurer, three army officers as one of the Nine Ministers, more than a hundred feudal chancellors, commandery governors, and two-thousand-bushel officials, and more than a thousand below that rank; strivers received offices beyond their hopes, while those who went because of banishment-faults had their merit dismissed; soldiers were given forty thousand cash each." },
  { zh: "匈奴聞貳師征大宛，欲遮之，貳師兵盛，不敢當，即遣騎因樓蘭候漢使後過者，欲絕勿通。", literal: "The Xiongnu heard the Eshi army was campaigning against Dayuan and wished to intercept it; the Eshi troops were strong and they dared not confront them, so they immediately sent horsemen by way of Loulan to watch for Han envoys passing afterward, wishing to cut them off and not let them through.", idiomatic: "The Xiongnu heard the Eshi army was campaigning against Dayuan and wished to intercept it; the Eshi troops were too strong to confront, so they sent horsemen through Loulan to watch for Han envoys passing afterward, intending to cut them off." },
  { zh: "時漢軍正任文將兵屯玉門關，捕得生口，知狀以聞。", literal: "At this time Han troops under Zheng Ren Wen were garrisoning at Yumen Pass; they captured a living captive, learned the situation, and reported it.", idiomatic: "At this time Han troops under Zheng Ren Wen were garrisoned at Yumen Pass; they captured a prisoner, learned the situation, and reported it." },
  { zh: "上詔文便道引兵捕樓蘭王，將詣闕簿責。", literal: "The emperor ordered Wen by the convenient route to lead troops and seize the King of Loulan, to bring him to the palace for register and censure.", idiomatic: "The emperor ordered Wen to take the convenient route, lead troops to seize the King of Loulan, and bring him to court for accounting." },
  { zh: "王對曰：「小國在大國間，不兩屬無以自安，願徙國入居漢地。", literal: "The king replied, saying: \"A small state between great states—without serving both one cannot secure oneself; your servant wishes to move the state and enter to dwell in Han territory.", idiomatic: "The king replied, \"A small state between great powers cannot secure itself without serving both; your servant wishes to move the state and settle within Han territory." },
  { zh: "」上直其言，遣歸國，亦因使候司匈奴，匈奴自是不甚親信樓蘭。", literal: "\" The emperor considered his words correct, sent him back to his state, and also by this envoy had him spy on the Xiongnu; from this the Xiongnu were not very trusting of Loulan.", idiomatic: "\" The emperor accepted his words, sent him back to his state, and also used him to spy on the Xiongnu; from this the Xiongnu no longer trusted Loulan much." },
  { zh: "自大宛破後，西域震懼，漢使入西域者益得職。", literal: "After Dayuan was broken, the Western Regions were shaken with fear; Han envoys entering the Western Regions increasingly obtained their duties.", idiomatic: "After Dayuan was defeated, the Western Regions were shaken with fear, and Han envoys in the Western Regions were increasingly able to perform their duties." },
  { zh: "於是自敦煌西至鹽澤往往起亭，而輪台、渠犁皆有田卒數百人，置使者、校尉領護，以給使外國者。", literal: "Thereupon from Dunhuang west to Salt Marsh watchtowers were raised here and there; moreover Luntai and Quli each had several hundred farming soldiers, with envoys and colonels set to lead and guard, to supply those serving foreign states.", idiomatic: "Thereupon from Dunhuang west to Salt Marsh watchtowers were built throughout, and Luntai and Quli each had several hundred farming soldiers, with envoys and colonels appointed to guard and supply those serving foreign states." },
  { zh: "後歲餘，宛貴人以為昧蔡善諛，使我國遇屠，乃相與殺昧蔡，立毋寡昆弟蟬封為宛王，而遣其子入侍於漢。", literal: "More than a year later, Dayuan nobles thought Mei Cai was skilled at flattery and had made our state meet slaughter; they thereupon together killed Mei Cai and installed Wugua's younger brother Chanfeng as King of Dayuan, and sent his son to attend at Han.", idiomatic: "More than a year later, Dayuan nobles thought Mei Cai was skilled at flattery and had brought slaughter upon their state; they killed Mei Cai and installed Wugua's younger brother Chanfeng as King of Dayuan, and sent his son to attend at Han." },
  { zh: "漢因使使賂賜，以鎮撫之。", literal: "Han thereupon sent envoys with bribes and gifts to pacify and comfort them.", idiomatic: "Han thereupon sent envoys with gifts to pacify them." },
  { zh: "蟬封與漢約，歲獻天馬二匹。", literal: "Chanfeng made a pact with Han to present two heavenly horses each year.", idiomatic: "Chanfeng agreed with Han to present two heavenly horses each year." },
  { zh: "----2秋，起明光宮。", literal: "----2 In autumn, the Mingguang Palace was raised.", idiomatic: "----2 In autumn the Mingguang Palace was built." },
  { zh: "----3冬，上行幸回中。", literal: "----3 In winter, the emperor traveled in favor to Huizhong.", idiomatic: "----3 In winter the emperor traveled to Huizhong." },
  { zh: "----4匈奴呴犁湖單于死，匈奴立其弟左大都尉且鞮侯為單于。", literal: "----4 The Xiongnu chanyu Hulu died; the Xiongnu installed his younger brother, the Left Grand Commander Qiedihou, as chanyu.", idiomatic: "----4 The Xiongnu chanyu Hulu died; the Xiongnu installed his younger brother, the Left Grand Commander Qiedihou, as chanyu." },
  { zh: "天子欲因伐宛之威遂困胡，乃下詔曰：「高皇帝遺朕平城之憂，-{高后}-時，單于書絕悖逆。", literal: "The Son of Heaven wished to take advantage of the prestige of attacking Dayuan to thereupon press the Hu, and issued an edict, saying: \"The High Emperor left Us the worry of Pingcheng; in the time of -{Empress Gao}-, the chanyu's letter was utterly rebellious and perverse.", idiomatic: "The emperor wished to use the prestige of the Dayuan campaign to press the Xiongnu and issued an edict, saying, \"The High Emperor left me the worry of Pingcheng; in the time of -{Empress Gao}-, the chanyu's letter was utterly rebellious." },
  { zh: "昔齊襄公復九世之讎，《春秋》大之。", literal: "Formerly Duke Xiang of Qi avenged a feud of nine generations—the Spring and Autumn Annals praise it.", idiomatic: "Formerly Duke Xiang of Qi avenged a feud of nine generations—the Spring and Autumn Annals praise it." },
  { zh: "」且鞮侯單于初立，恐漢襲之，乃曰：「我兒子，安敢望漢天子！", literal: "\" Chanyu Qiedihou had just been installed and feared Han would strike him; he thereupon said: \"I am his son—how would I dare look toward the Han Son of Heaven!", idiomatic: "\" Chanyu Qiedihou had just been installed and feared a Han attack; he said, \"I am his son—how would I dare look toward the Han emperor!" },
  { zh: "漢天子，我丈人行也。", literal: "The Han Son of Heaven is my wife's father's senior.", idiomatic: "The Han emperor is my father-in-law." },
  { zh: "」因盡歸漢使之不降者路充國等，使使來獻。", literal: "\" He thereupon completely returned Han envoys who had not submitted, such as Lu Chongguo, and sent envoys to come and present tribute.", idiomatic: "\" He thereupon returned all Han envoys who had not submitted, such as Lu Chongguo, and sent envoys to present tribute." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1 In spring, the first month, the emperor traveled in favor to Sweet Springs and suburban-sacrificed at the Great Altar.", idiomatic: "1 In spring, the first month, the emperor traveled to Sweet Springs and performed suburban sacrifice at the Great Altar." },
  { zh: "三月，行幸河東，祠-{后土}-。", literal: "In the third month, he traveled in favor to Hedong and sacrificed to -{Earth Queen}-.", idiomatic: "In the third month he traveled to Hedong and sacrificed to -{Earth Queen}-." },
  { zh: "----2上嘉匈奴單于之義，遣中郎將蘇武送匈奴使留在漢者，因厚賂單于，答其善意。", literal: "----2 The emperor praised the Xiongnu chanyu's righteousness and sent Palace Gentleman Su Wu to escort Xiongnu envoys detained in Han, and thereby richly bribed the chanyu to answer his good intent.", idiomatic: "----2 The emperor praised the Xiongnu chanyu's righteousness and sent Palace Gentleman Su Wu to escort Xiongnu envoys detained in Han, richly bribing the chanyu to answer his good intent." },
  { zh: "武與副中郎將張勝與假吏常惠等俱。", literal: "Wu together with Deputy Palace Gentleman Zhang Sheng and acting clerk Chang Hui and others went.", idiomatic: "Wu went together with Deputy Palace Gentleman Zhang Sheng and acting clerk Chang Hui and others." },
  { zh: "既至匈奴，置幣遣單于。", literal: "Having reached the Xiongnu, they set out gifts and sent them to the chanyu.", idiomatic: "Having reached the Xiongnu, they presented gifts to the chanyu." },
  { zh: "單于益驕，非漢所望也。", literal: "The chanyu grew increasingly arrogant—not what Han had hoped for.", idiomatic: "The chanyu grew increasingly arrogant—not what Han had hoped for." },
  { zh: "會緱王與長水虞常等及衛律所將降者，陰相與謀劫單于母閼氏歸漢。", literal: "It happened that the Gou king, Changshui Yu Chang and others, and those who had surrendered led by Wei Lü secretly together plotted to seize the chanyu's mother the yanzhi and return to Han.", idiomatic: "It happened that the Gou king, Changshui Yu Chang and others, and the surrenderers led by Wei Lü secretly plotted together to seize the chanyu's mother the yanzhi and return to Han." },
  { zh: "衛律者，父故長水胡人，律善協律都尉李延年，延年薦言律使於匈奴，使還，聞延年家收，遂亡降匈奴。", literal: "Wei Lü—his father was formerly a Changshui Hu man; Lü was skilled with Director of Harmonizing the Pitch Pipes Li Yanian; Yanian recommended saying Lü should be sent to the Xiongnu; when the mission returned he heard Yanian's household was seized and thereupon fled and surrendered to the Xiongnu.", idiomatic: "Wei Lü—his father was formerly a Changshui Hu man; Lü was on good terms with Director of Harmonizing the Pitch Pipes Li Yanian; Yanian recommended that Lü be sent to the Xiongnu; when the mission returned he heard Yanian's household had been seized and fled to surrender to the Xiongnu." },
  { zh: "單于愛之，與謀國事，立為丁靈王。", literal: "The chanyu favored him, deliberated state affairs with him, and installed him as King of Dingling.", idiomatic: "The chanyu favored him, deliberated state affairs with him, and made him King of Dingling." },
  { zh: "虞常在漢時素與副張勝相知，私候勝曰：「聞漢天子甚怨衛律，常能為漢伏弩射殺之。", literal: "Yu Chang in Han times had long known Deputy Zhang Sheng; he privately waited on Sheng and said: \"I have heard the Han Son of Heaven greatly hates Wei Lü; Chang can for Han lie in ambush with crossbow and shoot and kill him.", idiomatic: "Yu Chang in Han times had long known Deputy Zhang Sheng; he privately approached Sheng and said, \"I have heard the Han emperor greatly hates Wei Lü; Chang can lie in ambush for Han with a crossbow and kill him." },
  { zh: "吾母、弟在漢，幸蒙其賞賜。", literal: "My mother and younger brother are in Han; I hope to receive their rewards and gifts.", idiomatic: "My mother and younger brother are in Han; I hope to receive their rewards." },
  { zh: "」張勝許之，以貨物與常。", literal: "\" Zhang Sheng promised him and gave goods to Chang.", idiomatic: "\" Zhang Sheng promised him and gave goods to Chang." },
  { zh: "後月餘，單于出獵，獨閼氏、子弟在，虞常等七十餘人欲發，其一人夜亡告之。", literal: "More than a month later the chanyu went out hunting; only the yanzhi and sons and younger brothers remained; Yu Chang and more than seventy men wished to rise, but one man fled by night and reported it.", idiomatic: "More than a month later the chanyu went hunting; only the yanzhi and his sons and younger brothers remained; Yu Chang and more than seventy men wished to act, but one man fled by night and reported it." },
  { zh: "單于子弟發兵與戰，緱王等皆死，虞常生得。", literal: "The chanyu's sons and younger brothers raised troops and fought; the Gou king and others all died; Yu Chang was taken alive.", idiomatic: "The chanyu's sons and younger brothers raised troops and fought; the Gou king and others all died; Yu Chang was captured alive." },
  { zh: "單于使衛律治其事。", literal: "The chanyu had Wei Lü handle the matter.", idiomatic: "The chanyu had Wei Lü handle the matter." },
  { zh: "張勝聞之，恐前語發，以狀語武。", literal: "Zhang Sheng heard of it, feared their earlier words would be exposed, and told Wu the situation.", idiomatic: "Zhang Sheng heard of it, feared their earlier words would be exposed, and told Wu the situation." },
  { zh: "武曰：「事如此，此必及我，見犯乃死，重負國。", literal: "Wu said: \"The affair being like this, this will surely reach me; to be violated and then die heavily burdens the state.", idiomatic: "Wu said, \"The affair being like this, this will surely reach me; to be violated and then die would heavily burden the state." },
  { zh: "」欲自殺。", literal: "\" He wished to kill himself.", idiomatic: "\" He wished to kill himself." },
  { zh: "勝、惠共止之。", literal: "Sheng and Hui together stopped him.", idiomatic: "Sheng and Hui together stopped him." },
  { zh: "虞常果引張勝。", literal: "Yu Chang indeed implicated Zhang Sheng.", idiomatic: "Yu Chang indeed implicated Zhang Sheng." },
  { zh: "單于怒，召諸貴人議，欲殺漢使者。", literal: "The chanyu was enraged, summoned the various nobles to deliberate, and wished to kill the Han envoys.", idiomatic: "The chanyu was enraged, summoned the nobles to deliberate, and wished to kill the Han envoys." },
  { zh: "左伊秩訾曰：「即謀單于，何以復加！", literal: "Left Yizhi Ze said: \"If they already plotted against the chanyu, how can one add more!", idiomatic: "Left Yizhi Ze said, \"If they already plotted against the chanyu, how can one add more!" },
  { zh: "宜皆降之。", literal: "They should all be made to surrender.", idiomatic: "They should all be made to surrender." },
  { zh: "」單于使衛律召武受辭。", literal: "\" The chanyu had Wei Lü summon Wu to receive his confession.", idiomatic: "\" The chanyu had Wei Lü summon Wu to take his confession." },
  { zh: "武謂惠等：「屈節辱命，雖生，何面目以歸漢！", literal: "Wu said to Hui and the others: \"To bend one's integrity and disgrace one's commission—even living, with what face could one return to Han!", idiomatic: "Wu said to Hui and the others, \"To bend one's integrity and disgrace one's commission—even living, with what face could one return to Han!" },
  { zh: "」引佩刀自刺。", literal: "\" He drew his girdle knife and stabbed himself.", idiomatic: "\" He drew his girdle knife and stabbed himself." },
  { zh: "衛律驚，自抱持武，馳召醫，鑿地為坎，置熅火，覆武其上，蹈其背以出血。", literal: "Wei Lü was startled, himself embraced and held Wu, galloped to summon a physician, dug the ground into a pit, set smoldering fire, covered Wu above it, and trod his back to draw out blood.", idiomatic: "Wei Lü was startled, himself embraced Wu, galloped to summon a physician, dug a pit in the ground, set smoldering fire, covered Wu with it, and trod his back to draw out blood." },
  { zh: "武氣絕，半日復息。", literal: "Wu's breath was cut off; after half a day he breathed again.", idiomatic: "Wu's breath stopped; after half a day he breathed again." },
  { zh: "惠等哭，輿歸營。", literal: "Hui and the others wept and carried him back to camp in a litter.", idiomatic: "Hui and the others wept and carried him back to camp in a litter." },
  { zh: "單于壯其節，朝夕遣人候問武，而收系張勝。", literal: "The chanyu admired his integrity, morning and evening sent men to inquire after Wu, and detained Zhang Sheng.", idiomatic: "The chanyu admired his integrity, sent men morning and evening to inquire after Wu, and detained Zhang Sheng." },
  { zh: "武益愈，單于使使曉武，欲降之，會論虞常，欲因此時降武；", literal: "Wu grew increasingly recovered; the chanyu sent envoys to enlighten Wu, wishing to make him surrender; it happened they judged Yu Chang, wishing thereby to make Wu surrender at this time;", idiomatic: "As Wu recovered, the chanyu sent envoys to persuade Wu to surrender; it happened they judged Yu Chang, wishing thereby to make Wu surrender at that moment;" },
  { zh: "劍斬虞常已，律曰：「漢使張勝謀殺單于近臣，當死，單于募降者赦罪。", literal: "having already beheaded Yu Chang with the sword, Lü said: \"Han envoy Zhang Sheng plotted to kill the chanyu's close minister—he should die; the chanyu recruits surrenderers and pardons crime.", idiomatic: "having beheaded Yu Chang with the sword, Lü said, \"Han envoy Zhang Sheng plotted to kill the chanyu's close minister—he should die; the chanyu recruits surrenderers and pardons crime." },
  { zh: "」舉劍欲擊之，勝請降。", literal: "\" He raised the sword wishing to strike him; Sheng requested to surrender.", idiomatic: "\" He raised the sword to strike him; Sheng asked to surrender." },
  { zh: "律謂武曰：「副有罪，當相坐。", literal: "Lü said to Wu: \"The deputy has crime; you should share punishment.", idiomatic: "Lü said to Wu, \"The deputy is guilty; you should share punishment." },
  { zh: "」武曰：「本無謀，又非親屬，何謂相坐！", literal: "\" Wu said: \"Originally there was no plotting, and moreover we are not kin—what is meant by sharing punishment!", idiomatic: "\" Wu said, \"Originally there was no plotting, and moreover we are not kin—what is meant by sharing punishment!" },
  { zh: "」復舉劍擬之，武不動。", literal: "\" He again raised the sword and gestured at him; Wu did not move.", idiomatic: "\" He again raised the sword and gestured at him; Wu did not move." },
  { zh: "律曰：「蘇君，律前負漢歸匈奴，幸蒙大恩賜號稱王，擁眾數萬，馬畜彌山，富貴如此！", literal: "Lü said: \"Master Su—Lü formerly turned his back on Han and returned to the Xiongnu; fortunately I received great favor, was granted a title and styled king, hold masses of several tens of thousands, horses and livestock fill the mountains—wealth and honor like this!", idiomatic: "Lü said, \"Master Su—Lü formerly turned his back on Han and returned to the Xiongnu; fortunately I received great favor, was granted a title and styled king, hold masses of tens of thousands, horses and livestock fill the mountains—wealth and honor like this!" },
  { zh: "蘇君今日降，明日復然；", literal: "Master Su, if you surrender today, tomorrow will be the same again;", idiomatic: "Master Su, if you surrender today, tomorrow will be the same again;" },
  { zh: "空以身膏草野，誰復知之！", literal: "in vain you would make your body grease the wild grass—who would know you again!", idiomatic: "in vain you would make your body grease the wild grass—who would know you again!" },
  { zh: "」武不應。", literal: "\" Wu did not respond.", idiomatic: "\" Wu did not respond." },
  { zh: "律曰：「君因我降，與君為兄弟；", literal: "Lü said: \"If you surrender through me, I will be brothers with you;", idiomatic: "Lü said, \"If you surrender through me, I will be brothers with you;" },
  { zh: "今不聽吾計，後雖欲復見我，尚可得乎！", literal: "now if you do not heed my plan, later even if you wish again to see me, can you still obtain it!", idiomatic: "now if you do not heed my plan, later even if you wish again to see me, can you still obtain it!" },
  { zh: "」武罵律曰：「汝為人臣子，不顧恩義，畔主背親，為降虜於蠻夷，何以汝為見！", literal: "\" Wu cursed Lü, saying: \"You are a man's minister and son, yet do not think of grace and righteousness, turn your back on your lord and abandon your kin, become a surrendering captive among barbarians—why should I see you!", idiomatic: "\" Wu cursed Lü, saying, \"You are a man's minister and son, yet do not think of grace and righteousness, turn your back on your lord and abandon your kin, become a surrendering captive among barbarians—why should I see you!" },
  { zh: "且單于信汝，使決人死生，不平心持正，反欲鬥兩主，觀禍敗。", literal: "Moreover the chanyu trusts you and has you decide men's life and death; you do not hold your heart level and straight, yet wish instead to set the two lords fighting and watch disaster and defeat.", idiomatic: "Moreover the chanyu trusts you and has you decide men's life and death; you do not hold your heart level and straight, yet wish instead to set the two rulers fighting and watch disaster and defeat." },
  { zh: "南越殺漢使者，屠為九郡；", literal: "Nanyue killed Han envoys and was slaughtered into nine commanderies;", idiomatic: "Nanyue killed Han envoys and was slaughtered into nine commanderies;" },
  { zh: "宛王殺漢使者，頭懸北闕；", literal: "the King of Dayuan killed Han envoys and his head hung at the northern gate;", idiomatic: "the King of Dayuan killed Han envoys and his head hung at the northern gate;" },
  { zh: "朝鮮殺漢使者，即時誅滅；", literal: "Chaoxian killed Han envoys and was immediately exterminated;", idiomatic: "Chaoxian killed Han envoys and was immediately exterminated;" },
  { zh: "獨匈奴未耳。", literal: "only the Xiongnu have not yet.", idiomatic: "only the Xiongnu have not yet." },
  { zh: "若知我不降明，欲令兩國相攻，匈奴之禍從我始矣。", literal: "If you know clearly that I will not surrender, you wish to make the two states attack each other—the Xiongnu's disaster will begin with me.", idiomatic: "If you know clearly that I will not surrender, you wish to make the two states attack each other—the Xiongnu's disaster will begin with me." },
  { zh: "」律知武終不可脅，白單于，單于愈益欲降之。", literal: "\" Lü knew Wu in the end could not be coerced, reported to the chanyu, and the chanyu increasingly wished to make him surrender.", idiomatic: "\" Lü knew Wu in the end could not be coerced, reported to the chanyu, and the chanyu increasingly wished to make him surrender." },
  { zh: "乃幽武置大窖中，絕不飲食；", literal: "He thereupon imprisoned Wu and placed him in a great cellar, cutting off all drink and food;", idiomatic: "He imprisoned Wu in a great cellar and cut off all drink and food;" },
  { zh: "天雨雪，武臥，嚙雪與旃毛並咽之，數日不死。", literal: "Heaven snowed rain; Wu lay down, chewed snow together with felt fur and swallowed it, and several days did not die.", idiomatic: "It snowed; Wu lay down, chewed snow together with felt fur and swallowed it, and did not die for several days." },
  { zh: "匈奴以為神，乃徙武北海上無人處，使牧羝，曰：「羝乳乃得歸。", literal: "The Xiongnu thought him divine; he thereupon moved Wu to the northern sea frontier where no men were, had him herd rams, and said: \"When the rams give milk you may return.", idiomatic: "The Xiongnu thought him divine; they moved Wu to the northern sea frontier where no men were, had him herd rams, and said, \"When the rams give milk you may return." },
  { zh: "」別其官屬常惠等，各置他所。", literal: "\" He separated his attendant officials Chang Hui and others, each placed in another place.", idiomatic: "\" They separated his attendants Chang Hui and others, each placed elsewhere." },
  { zh: "----3天雨白牦。", literal: "----3 Heaven rained white yak.", idiomatic: "----3 Heaven rained white yak." },
  { zh: "----4夏，大旱。", literal: "----4 In summer, great drought.", idiomatic: "----4 In summer there was great drought." },
  { zh: "----5五月，赦天下。", literal: "----5 In the fifth month, an amnesty for all under Heaven.", idiomatic: "----5 In the fifth month there was an amnesty for all under Heaven." },
  { zh: "----6發謫戍屯五原。", literal: "----6 Conscripted banishment-garrison troops were sent to garrison Wuyuan.", idiomatic: "----6 Banishment-garrison troops were sent to garrison Wuyuan." },
  { zh: "----7浞野侯趙破奴自匈奴亡歸。", literal: "----7 Marquis of Zhuoye Zhao Ponu fled from the Xiongnu and returned.", idiomatic: "----7 Marquis of Zhuoye Zhao Ponu fled from the Xiongnu and returned." },
  { zh: "----8是歲，濟南太守王卿為御史大夫。", literal: "----8 This year, Jinan Administrator Wang Qing became Censor-in-Chief.", idiomatic: "----8 This year Jinan Administrator Wang Qing became Censor-in-Chief." },
  { zh: "1春，上行幸東海。", literal: "1 In spring, the emperor traveled in favor to the Eastern Sea.", idiomatic: "1 In spring the emperor traveled to the Eastern Sea." },
  { zh: "還，幸回中。", literal: "Returning, he favored Huizhong.", idiomatic: "On his return he traveled to Huizhong." },
  { zh: "----2夏，五月，遣貳師將軍廣利以三萬騎出酒泉，擊右賢王於天山，得胡首虜萬餘級而還。", literal: "----2 In summer, the fifth month, Eshi General Guangli was sent with thirty thousand horsemen out from Jiuquan to strike the Right Worthy King at Heavenly Mountain, obtaining more than ten thousand Hu heads and captives and returning.", idiomatic: "----2 In summer, the fifth month, Eshi General Guangli was sent with thirty thousand horsemen from Jiuquan to strike the Right Worthy King at Heavenly Mountain, taking more than ten thousand Xiongnu heads and captives and returning." },
  { zh: "匈奴大圍貳師將軍，漢軍乏食數日，死傷者多。", literal: "The Xiongnu greatly besieged the Eshi general; Han troops lacked food for several days and many died or were wounded.", idiomatic: "The Xiongnu greatly besieged the Eshi general; Han troops lacked food for several days and many died or were wounded." },
  { zh: "假司馬隴西趙充國與士百餘人潰圍陷陳，貳師引兵隨之，遂得解。", literal: "Acting Major Longxi Zhao Chongguo with more than a hundred soldiers broke the encirclement and charged the formation; the Eshi general led troops following them and thereupon obtained relief.", idiomatic: "Acting Major Longxi Zhao Chongguo with more than a hundred soldiers broke the encirclement and charged the formation; the Eshi general led troops after them and was thereby relieved." },
  { zh: "漢兵物故什六七，充國身被二十餘創。", literal: "Han troops perished seven or eight in ten; Chongguo himself received more than twenty wounds.", idiomatic: "Han troops lost seven or eight in ten; Chongguo himself received more than twenty wounds." },
  { zh: "貳師奏狀，詔征充國詣行在所，帝親見，視其創，嗟歎之，拜為中郎。", literal: "The Eshi general memorialized the situation; an edict summoned Chongguo to the traveling palace; the emperor personally saw him, looked at his wounds, sighed and praised him, and appointed him Palace Gentleman.", idiomatic: "The Eshi general memorialized the situation; an edict summoned Chongguo to the traveling palace; the emperor personally saw him, looked at his wounds, sighed and praised him, and appointed him Palace Gentleman." },
  { zh: "漢復使因杅將軍敖出西河，與強弩都尉路博德會涿塗山，無所得。", literal: "Han again sent Yinya General Ao out from Xihe to meet Strong Crossbow Colonel Lu Bode at Zhuotu Mountain—nothing obtained.", idiomatic: "Han again sent Yinya General Ao out from Xihe to meet Strong Crossbow Colonel Lu Bode at Zhuotu Mountain and obtained nothing." },
  { zh: "初，李廣有孫陵，為侍中，善騎射，愛人下士。", literal: "Initially, Li Guang had a grandson Ling, who was Palace Attendant, skilled at mounted archery, and loved men and humbled himself before scholars.", idiomatic: "Initially Li Guang had a grandson Ling, who was Palace Attendant, skilled at mounted archery, and loved men and humbled himself before scholars." },
  { zh: "帝以為有廣之風，拜騎都尉，使將丹陽、楚人五千人，教射酒泉、張掖以備胡。", literal: "The emperor thought he had Guang's manner, appointed him Cavalry Commandant, and had him lead five thousand men of Danyang and Chu, teaching archery at Jiuquan and Zhangye to prepare against the Hu.", idiomatic: "The emperor thought he had Guang's manner, appointed him Cavalry Commandant, and had him lead five thousand men of Danyang and Chu to teach archery at Jiuquan and Zhangye against the Xiongnu." },
  { zh: "及貳師擊匈奴，上詔陵，欲使為貳師將輜重，陵叩頭自請曰：「臣所將屯邊者，皆荊楚勇士奇材劍客也，力扼虎，射命中，願得自當一隊，到-{蘭于}-山南以分單于兵，毋令專向貳師軍。", literal: "When the Eshi army struck the Xiongnu, the emperor ordered Ling, wishing to have him for the Eshi general lead baggage trains; Ling knocked his head and requested himself, saying: \"Those your servant leads garrisoning the border are all Jing-Chu warriors of strange talent and sword guests—strength to throttle tigers, shooting that hits the mark; your servant wishes to take a separate command, reach south of -{Lan Yu}- Mountain to divide the chanyu's troops, and not let them focus solely on the Eshi army.", idiomatic: "When the Eshi army struck the Xiongnu, the emperor ordered Ling, wishing to have him lead baggage trains for the Eshi general; Ling knocked his head and requested himself, saying, \"Those your servant leads garrisoning the border are all Jing-Chu warriors of strange talent and swordsmen—strength to throttle tigers, shooting that hits the mark; your servant wishes to take a separate command, reach south of -{Lan Yu}- Mountain to divide the chanyu's troops, and not let them focus solely on the Eshi army." },
  { zh: "」上曰：「將惡相屬邪！", literal: "\" The emperor said: \"Do generals dislike being subordinate to one another!", idiomatic: "\" The emperor said, \"Do generals dislike being subordinate to one another!" },
  { zh: "吾發軍多，無騎予女。", literal: "I am sending out many armies and have no cavalry to give you.", idiomatic: "I am sending out many armies and have no cavalry to give you." },
  { zh: "」陵對：「無所事騎，臣願以少擊眾，步兵五千人涉單于庭。", literal: "\" Ling replied: \"Without needing cavalry, your servant wishes with few to strike many—five thousand foot soldiers crossing the chanyu's court.", idiomatic: "\" Ling replied, \"Without needing cavalry, your servant wishes with few to strike many—five thousand foot soldiers crossing the chanyu's court." },
  { zh: "」上壯而許之。", literal: "\" The emperor was impressed and assented.", idiomatic: "\" The emperor was impressed and assented." },
  { zh: "因詔路博德將兵半道迎陵軍。", literal: "He thereupon ordered Lu Bode to lead troops halfway to meet Ling's army.", idiomatic: "He thereupon ordered Lu Bode to lead troops halfway to meet Ling's army." },
  { zh: "博德亦羞為陵後距，奏言：「方秋，匈奴馬肥，未可與戰，願留陵至春俱出。", literal: "Bode also was ashamed to be Ling's rear support and memorialized, saying: \"It is just autumn; Xiongnu horses are fat and one cannot yet fight them; your servant wishes to keep Ling until spring and go out together.", idiomatic: "Bode was also ashamed to be Ling's rear support and memorialized, saying, \"It is just autumn; Xiongnu horses are fat and one cannot yet fight them; your servant wishes to keep Ling until spring and go out together." },
  { zh: "」上怒，疑陵悔不欲出而教博德上書，乃詔博德引兵擊匈奴於西河。", literal: "\" The emperor was enraged, suspected Ling regretted and did not wish to go out and had taught Bode to memorialize, and thereupon ordered Bode to lead troops and strike the Xiongnu in Xihe.", idiomatic: "\" The emperor was enraged, suspected Ling regretted going out and had coached Bode to memorialize, and ordered Bode to lead troops and strike the Xiongnu in Xihe." },
  { zh: "詔陵以九月發，出遮虜障，至東浚稽山南龍勒水上，徘徊觀虜，即亡所見，還，抵受降城休士。", literal: "He ordered Ling to set out in the ninth month, go out through the barrier that blocks the barbarians, reach south of Eastern Junji Mountain at Dragon Rein River, linger and observe the barbarians—immediately nothing was seen—and return, reaching Surrender-Receiving City to rest the soldiers.", idiomatic: "He ordered Ling to set out in the ninth month, go out through the barbarian-blocking barrier to south of Eastern Junji Mountain at Dragon Rein River, linger to observe the barbarians—seeing nothing—and return to Surrender-Receiving City to rest his troops." },
  { zh: "陵於是將其步卒五千人，出居延，北行三十日，至浚稽山止營，舉圖所過山川地形，使麾下騎陳步樂還以聞。", literal: "Ling thereupon led his five thousand foot soldiers, went out from Juyan, marched north thirty days, reached Junji Mountain and halted camp, raised a map of the mountains and rivers and terrain passed through, and sent his subordinate cavalryman Chen Bule back to report.", idiomatic: "Ling thereupon led his five thousand foot soldiers out from Juyan, marched north thirty days to Junji Mountain and halted camp, mapped the mountains, rivers, and terrain passed through, and sent his subordinate cavalryman Chen Bule back to report." },
  { zh: "步樂召見，道陵將率得士死力，上甚悅，拜步樂為郎。", literal: "Bule was summoned to audience; he spoke of how Ling as general obtained soldiers' death-strength; the emperor was very pleased and appointed Bule as Gentleman of the Palace.", idiomatic: "Bule was summoned to audience; he reported that Ling as general won his men's utmost loyalty; the emperor was very pleased and appointed Bule Gentleman of the Palace." },
  { zh: "陵至浚稽山，與單于相值，騎可三萬圍陵軍，軍居兩山間，以大車為營。", literal: "Ling reached Junji Mountain and met the chanyu head-on; horsemen numbering perhaps thirty thousand surrounded Ling's army; the army dwelt between two mountains, using great carts as camp.", idiomatic: "Ling reached Junji Mountain and met the chanyu head-on; perhaps thirty thousand horsemen surrounded Ling's army, which camped between two mountains using great carts as fortification." },
  { zh: "陵引士出營外為陳，前行持戟、盾，後行持弓、弩。", literal: "Ling led soldiers out beyond the camp to form a battle array: the front rank held halberds and shields, the rear rank held bows and crossbows.", idiomatic: "Ling led his men out beyond the camp to form a battle line: the front rank held halberds and shields, the rear rank bows and crossbows." },
  { zh: "虜見漢軍少，直前就營。", literal: "The barbarians saw the Han army was few and went straight forward to the camp.", idiomatic: "The barbarians saw the Han force was small and charged straight at the camp." },
  { zh: "陵搏戰攻之，千弩俱發，應弦而倒。", literal: "Ling fought hand to hand and struck them; a thousand crossbows fired together and they fell as the bowstrings answered.", idiomatic: "Ling fought hand to hand and struck them; a thousand crossbows fired together and the enemy fell as the strings sounded." },
  { zh: "虜還走上山，漢軍追擊殺數千人。", literal: "The barbarians turned back and ran up the mountain; the Han army pursued and killed several thousand men.", idiomatic: "The barbarians retreated up the mountain; the Han army pursued and killed several thousand." },
  { zh: "單于大驚，召左、右地兵八萬餘騎攻陵。", literal: "The chanyu was greatly startled and summoned left and right territorial troops—more than eighty thousand horsemen—to attack Ling.", idiomatic: "The chanyu was greatly startled and summoned left and right territorial troops—more than eighty thousand horsemen—to attack Ling." },
  { zh: "陵且戰且引南行，數日，抵山谷中，連戰，士卒中矢傷，三創者載輦。", literal: "Ling fought while withdrawing south; after several days he reached a mountain valley; in continuous fighting soldiers were struck by arrows and wounded—those with three wounds were carried in litters.", idiomatic: "Ling fought while withdrawing south; after several days he reached a mountain valley; in continuous fighting his men were wounded by arrows—those with three wounds were carried in litters." },
  { zh: "兩創者將車，一創者持兵戰，復斬首三千餘級。", literal: "Those with two wounds drove the carts; those with one wound held weapons and fought; they again beheaded more than three thousand.", idiomatic: "Those with two wounds drove the carts; those with one wound fought with weapons in hand; they again took more than three thousand heads." },
  { zh: "引兵東南，循故龍城道行四五日，抵大澤葭葦中，虜從上風縱火，陵亦令軍中縱火以自救。", literal: "He led the army southeast, following the old Dragon City road for four or five days, reaching a great marsh of reeds; the barbarians set fire from upwind, and Ling also ordered the army to set fire to save themselves.", idiomatic: "He led his army southeast along the old Dragon City road for four or five days to a great marsh of reeds; the barbarians set fire from upwind, and Ling also ordered his men to set fire to save themselves." },
  { zh: "南行至山下，單于在南山上，使其子將騎擊陵。", literal: "Marching south to below the mountain, the chanyu was on the southern mountain and sent his son to lead horsemen and strike Ling.", idiomatic: "Marching south to the foot of the mountain, the chanyu was on the southern slope and sent his son to lead horsemen against Ling." },
  { zh: "陵軍步鬥樹木間，復殺數千人，因發連弩射單于，單于下走。", literal: "Ling's army fought on foot among the trees, again killing several thousand; they thereupon loosed repeating crossbows to shoot the chanyu, and the chanyu ran down.", idiomatic: "Ling's army fought on foot among the trees and again killed several thousand; they then loosed repeating crossbows at the chanyu, and the chanyu fled downhill." },
  { zh: "是日捕得虜，言「單于曰：『此漢精兵，擊之不能下，日夜引吾南近塞，得無有伏兵乎？", literal: "That day they captured a barbarian who said: \"The chanyu said: 'These are Han elite troops; striking them we cannot take them down; day and night they draw me south near the passes—is there perhaps an ambush?", idiomatic: "That day they captured a barbarian who said, \"The chanyu said, 'These are Han elite troops; we cannot bring them down; day and night they draw me south near the passes—is there perhaps an ambush?" },
  { zh: "』諸當戶君長皆言：『單于自將數萬騎擊漢數千人不能滅，後無以復使邊臣，令漢益輕匈奴。", literal: "' The various household chieftains all said: 'The chanyu himself leading tens of thousands of horsemen could not destroy several thousand Han; afterward there will be no way to send border ministers again—this will make Han increasingly look down on the Xiongnu.", idiomatic: "' The various household chieftains all said, 'The chanyu himself leading tens of thousands of horsemen could not destroy several thousand Han; afterward there will be no way to use border ministers again—Han will look down on the Xiongnu all the more." },
  { zh: "復力戰山谷間，尚四五十里，得平地，不能破，乃還。", literal: "Fight again in the mountain valleys; still forty or fifty li to level ground; if we cannot break them, then return.", idiomatic: "Fight again in the mountain valleys; still forty or fifty li to level ground; if we cannot break them, then return." },
  { zh: "是時陵軍益急，匈奴騎多，戰一日數十合，復傷殺虜二千餘人。", literal: "At this time Ling's army grew increasingly pressed; Xiongnu horsemen were many; in one day they fought several tens of engagements and again wounded and killed more than two thousand barbarians.", idiomatic: "At this time Ling's army grew increasingly pressed; Xiongnu horsemen were many; in one day they fought dozens of engagements and again wounded and killed more than two thousand barbarians." },
  { zh: "虜不利，欲去，會陵軍候管敢為校尉所辱，亡降匈奴，具言：「陵軍無後救，射矢且盡，獨將軍麾下及校尉成安侯韓延年各八百人為前行，以黃與白為幟。", literal: "The barbarians were disadvantaged and wished to leave; it happened that Ling's army scout Guan Gan had been insulted by a colonel, fled and surrendered to the Xiongnu, and fully stated: \"Ling's army has no rear relief; shooting arrows are nearly exhausted; only the general's personal followers and Colonel Marquis of Cheng'an Han Yannian, eight hundred each, are the forward rank, using yellow and white as banners.", idiomatic: "The barbarians were at a disadvantage and wished to withdraw; it happened that Ling's army scout Guan Gan had been insulted by a colonel, fled and surrendered to the Xiongnu, and fully reported, \"Ling's army has no rear relief; arrows are nearly spent; only the general's personal followers and Colonel Marquis of Cheng'an Han Yannian, eight hundred men each, form the forward rank, with yellow and white as their banners." },
  { zh: "當使精騎射之，即破矣。", literal: "One should send elite horsemen to shoot them—then they will be broken at once.", idiomatic: "Send elite horsemen to shoot them and they will be broken at once." },
  { zh: "」單于得敢大喜，使騎並攻漢軍，疾呼曰：「李陵、韓延年趣降！", literal: "\" The chanyu, obtaining Gan, was greatly pleased, sent horsemen together to attack the Han army, and urgently shouted: \"Li Ling and Han Yannian—hurry and surrender!", idiomatic: "\" The chanyu, obtaining Gan, was greatly pleased, sent horsemen together to attack the Han army, and urgently shouted, \"Li Ling and Han Yannian—hurry and surrender!" },
  { zh: "」遂遮道急攻陵。", literal: "\" He thereupon blocked the road and urgently attacked Ling.", idiomatic: "\" He thereupon blocked the road and urgently attacked Ling." },
  { zh: "陵居谷中，虜在山上，四面射，矢如雨下。", literal: "Ling dwelt in the valley; the barbarians were on the mountain; they shot from four sides and arrows fell like rain.", idiomatic: "Ling was in the valley while the barbarians were on the mountain; they shot from four sides and arrows fell like rain." },
  { zh: "漢軍南行，未至鞮汗山，一日五十萬矢皆盡，即棄車去。", literal: "The Han army marched south; before reaching Dihan Mountain, in one day five hundred thousand arrows were all exhausted; they immediately abandoned the carts and left.", idiomatic: "The Han army marched south; before reaching Dihan Mountain, in one day five hundred thousand arrows were all spent; they immediately abandoned the carts." },
  { zh: "士尚三千餘人，徒斬車輻而持之，軍吏持尺刀，抵山，入狹谷，單于遮其後，乘隅下壘石，士卒多死，不得行。", literal: "Soldiers still numbered more than three thousand; they only chopped cart wheel hubs to hold, army officers held foot-long knives; reaching the mountain they entered a narrow valley; the chanyu blocked their rear; from corners above they rolled down piled stones; soldiers mostly died and could not advance.", idiomatic: "More than three thousand soldiers remained; they chopped cart wheel hubs to wield as weapons, officers held foot-long knives; reaching the mountain they entered a narrow valley; the chanyu blocked their rear; from the heights they rolled down piled stones; many soldiers died and could not advance." },
  { zh: "昏後，陵便衣獨步出營，止左右：「毋隨，丈夫一取單于耳！", literal: "After dusk, Ling changed clothes and walked alone out of camp, stopping his attendants: \"Do not follow; a man should once take the chanyu's ear!", idiomatic: "After dusk Ling changed clothes and walked alone out of camp, stopping his attendants: \"Do not follow—a man should once take the chanyu's ear!" },
  { zh: "」良久，陵還，太息曰：「兵敗，死矣！", literal: "\" After a long while Ling returned, sighed deeply, and said: \"The army is defeated—I am as good as dead!", idiomatic: "\" After a long while Ling returned, sighed deeply, and said, \"The army is defeated—I am as good as dead!" },
  { zh: "」於是盡斬旌旗，及珍寶埋地中，陵歎曰：「復得數十矢，足以脫矣。", literal: "\" He thereupon completely cut down the banners and flags and buried treasures in the ground; Ling sighed and said: \"If I could again obtain several tens of arrows, it would be enough to escape.", idiomatic: "\" He thereupon cut down all banners and flags and buried treasures in the ground; Ling sighed and said, \"If I could obtain even several tens of arrows more, it would be enough to escape." },
  { zh: "今無兵復戰，天明，坐受縛矣。", literal: "Now without weapons to fight again, at daybreak I will sit and accept binding.", idiomatic: "Now without weapons to fight again, at daybreak I will sit and accept binding." },
  { zh: "各鳥獸散，猶有得脫歸報天子者。", literal: "Each like birds and beasts scatter—there may still be some who escape and return to report to the Son of Heaven.", idiomatic: "Each scatter like birds and beasts—some may still escape and return to report to the emperor." },
  { zh: "」令軍士人持二升糒，一片冰，期至遮障者相待。", literal: "\" He ordered the soldiers each to take two sheng of dry provisions and one piece of ice, fixing a time to meet at the blocking barrier.", idiomatic: "\" He ordered each soldier to take two sheng of dry provisions and one piece of ice, fixing a time to meet at the blocking barrier." },
  { zh: "夜半時，擊鼓起士，鼓不鳴。", literal: "At midnight he beat the drum to rouse the soldiers; the drum did not sound.", idiomatic: "At midnight he beat the drum to rouse the soldiers; the drum did not sound." },
  { zh: "陵與韓延年俱上馬，壯士從者十餘人，虜騎數千追之，韓延年戰死。", literal: "Ling and Han Yannian both mounted horses; stalwart followers numbered more than ten; several thousand barbarian horsemen pursued them; Han Yannian died fighting.", idiomatic: "Ling and Han Yannian both mounted; more than ten stalwarts followed; several thousand barbarian horsemen pursued them; Han Yannian died fighting." },
  { zh: "陵曰：「無面目報陛下！", literal: "Ling said: \"I have no face to report to Your Majesty!", idiomatic: "Ling said, \"I have no face to report to Your Majesty!" },
  { zh: "」遂降。", literal: "\" He thereupon surrendered.", idiomatic: "\" He thereupon surrendered." },
  { zh: "軍人分散，脫至塞者四百餘人。", literal: "The soldiers scattered; those who escaped to the passes numbered more than four hundred.", idiomatic: "The soldiers scattered; more than four hundred escaped to the passes." },
  { zh: "陵敗處去塞百餘里，邊塞以聞。", literal: "The place where Ling was defeated was more than a hundred li from the passes; the border passes reported it.", idiomatic: "The place where Ling was defeated was more than a hundred li from the passes; the border reported it." },
  { zh: "上欲陵死戰；", literal: "The emperor wished Ling to fight to the death;", idiomatic: "The emperor wished Ling to fight to the death;" },
  { zh: "後聞陵降，上怒甚，責問陳步樂，步樂自殺。", literal: "later hearing Ling had surrendered, the emperor was greatly enraged, censured and questioned Chen Bule, and Bule killed himself.", idiomatic: "later hearing Ling had surrendered, the emperor was greatly enraged, censured Chen Bule, and Bule killed himself." },
  { zh: "群臣皆罪陵，上以問太史令司馬遷，遷盛言：「陵事親孝，與士信，常奮不顧身以徇國家之急，其素所畜積也，有國士之風。", literal: "The host of ministers all blamed Ling; the emperor questioned Grand Astrologer Sima Qian; Qian strongly stated: \"Ling served his parents with filial piety, was faithful with soldiers, and constantly strove without regard for his body to follow the state's urgent needs—what he had long stored up; he had the manner of a state's scholar.", idiomatic: "The ministers all blamed Ling; the emperor questioned Grand Astrologer Sima Qian; Qian strongly argued, \"Ling served his parents filially, was faithful to his men, and constantly strove without regard for his body in the state's urgent need—what he had long cultivated; he had the manner of a state's finest man." },
  { zh: "今舉事一不幸，全軀保妻子之臣隨而媒糵其短，誠可痛也！", literal: "Now in one undertaking he met misfortune, yet ministers who preserve their bodies and protect wife and children follow to slander and magnify his faults—truly this is painful!", idiomatic: "Now in one misfortune, ministers who preserve their bodies and protect wife and children follow to slander and magnify his faults—truly this is painful!" },
  { zh: "且陵提步卒不滿五千，深蹂戎馬之地，抑數萬之師，虜救死扶傷不暇，悉舉引弓之民共攻圍之，轉鬥千里，矢盡道窮，士張空弮，冒白刃，北首爭死敵，得人之死力，雖古名將不過也。", literal: "Moreover Ling led foot soldiers not reaching five thousand, deeply trampled the land of barbarian horses, suppressed an army of tens of thousands; the barbarians had no leisure for rescuing the wounded and tending the hurt; they completely raised bow-drawing peoples together to attack and besiege him; he turned and fought a thousand li; arrows exhausted and the road ended; soldiers drew empty bowstocks, braved white blades, faced north striving to die against the enemy, obtaining men's death-strength—even ancient famed generals did not surpass this.", idiomatic: "Moreover Ling led fewer than five thousand foot soldiers, deeply invaded barbarian horse country, and held down an army of tens of thousands; the barbarians had no leisure to tend their wounded; they raised all their bowmen to attack and besiege him; he fought turning battle over a thousand li; arrows spent and the road ended; his men drew empty bowstocks, braved naked blades, faced north striving to die against the enemy, and won men's utmost loyalty—even ancient famed generals did not surpass this." },
  { zh: "身雖陷敗，然其所摧敗亦足暴於天下。", literal: "Though his person fell into defeat, yet what he crushed and defeated was also sufficient to be displayed to all under Heaven.", idiomatic: "Though he was defeated, what he crushed and defeated was still enough to display to the world." },
  { zh: "彼之不死，宜欲得當以報漢也。", literal: "That he did not die—he surely wished to obtain an occasion to repay Han.", idiomatic: "That he did not die—he surely wished to obtain an occasion to repay Han." },
  { zh: "」上以遷為誣罔，欲沮貳師，為陵遊說，下遷腐刑。", literal: "\" The emperor considered Qian's words deceptive and false, thought he wished to discourage the Eshi general and was lobbying for Ling, and sent Qian down to castration punishment.", idiomatic: "\" The emperor considered Qian's words deceptive, thought he wished to discourage the Eshi general and was lobbying for Ling, and imposed castration on Qian." },
  { zh: "久之，上悔陵無救，曰：「陵當發出塞，乃詔強弩都尉令迎軍；", literal: "After a long while the emperor regretted that Ling had no relief, and said: \"When Ling should have set out beyond the passes, I then ordered the Strong Crossbow Colonel to meet the army;", idiomatic: "After a long while the emperor regretted that Ling had no relief and said, \"When Ling should have set out beyond the passes, I had ordered the Strong Crossbow Colonel to meet his army;" },
  { zh: "坐預詔之，得令老將生奸詐。", literal: "because I announced it in advance, this allowed the old general to breed deceit.", idiomatic: "because I announced it in advance, this allowed the old general to breed deceit." },
  { zh: "」乃遣使勞賜陵餘軍得脫者。", literal: "\" He thereupon sent envoys to comfort and reward those of Ling's remaining army who had escaped.", idiomatic: "\" He thereupon sent envoys to comfort and reward those of Ling's remaining army who had escaped." },
  { zh: "----3上以法制御下，好尊用酷吏，而郡、國二千石為治者大抵多酷暴，吏民益輕犯法；", literal: "----3 The emperor used law to control subordinates and liked to honor and employ harsh clerks; moreover commandery and state two-thousand-bushel administrators governing were mostly harsh and violent; officials and people increasingly treated violating law lightly;", idiomatic: "----3 The emperor used law to control subordinates and liked to employ harsh clerks; commandery and state two-thousand-bushel administrators were mostly harsh and violent; officials and people increasingly treated breaking the law lightly;" },
  { zh: "東方盜賊滋起，大群至數千人，攻城邑，取庫兵，釋死罪，縛辱郡太守、都尉，殺二千石；", literal: "eastern bandits increasingly rose; large bands reached several thousand men, attacked cities and towns, seized arsenal weapons, released death-crime prisoners, bound and insulted commandery governors and commandants, and killed two-thousand-bushel officials;", idiomatic: "eastern bandits rose in force; large bands reached thousands, attacked cities and towns, seized arsenal weapons, released condemned men, bound and insulted commandery governors and commandants, and killed two-thousand-bushel officials;" },
  { zh: "小群以百數掠鹵鄉里者，不可勝數，道路不通。", literal: "small bands numbering in the hundreds plundering villages were beyond counting; roads were impassable.", idiomatic: "small bands of hundreds plundering villages were beyond counting; roads were impassable." },
  { zh: "上始使御史中丞、丞相長史督之，弗能禁；", literal: "The emperor at first sent the Vice Censor-in-Chief and the Chancellor's Chief Clerk to supervise them—they could not stop it;", idiomatic: "The emperor at first sent the Vice Censor-in-Chief and the Chancellor's Chief Clerk to supervise them but could not stop it;" },
  { zh: "乃使光祿大夫范昆及故九卿張德等衣繡衣，持節、虎符，發兵以興擊。", literal: "he thereupon sent Palace Counselor Fan Kun and former Nine Ministers Zhang De and others clothed in embroidered robes, holding credentials and tiger tallies, to raise troops and strike them down.", idiomatic: "he then sent Palace Counselor Fan Kun and former Nine Ministers Zhang De and others in embroidered robes, holding credentials and tiger tallies, to raise troops and strike them down." },
  { zh: "斬首大部或至萬餘級，及以法誅通行、飲食當連坐者，諸郡甚者數千人。", literal: "Beheaded in major cases sometimes reached more than ten thousand; moreover by law those executed for association in travel and eating and drinking reached several thousand in some commanderies.", idiomatic: "Major beheadings sometimes reached more than ten thousand; moreover those executed by law for association in travel and dining reached thousands in some commanderies." },
  { zh: "數歲，乃頗得其渠率，散卒失亡復聚黨阻山川者往往而群居，無可奈何。", literal: "Several years later they somewhat obtained their ringleaders; scattered soldiers who lost and fled and again gathered parties blocking mountains and rivers often grouped and dwelt together—nothing could be done.", idiomatic: "Several years later they somewhat captured ringleaders; scattered men who fled and again gathered in mountain strongholds often lived in groups—nothing could be done." },
  { zh: "於是作《沈命法》，曰：「群盜起，不發覺，發覺而捕弗滿品者，二千石以下至小吏，主者皆死。", literal: "Thereupon he made the Shenming Law, saying: \"When bandit gangs rise, if not discovered, or discovered but capture does not reach the quota, from two-thousand-bushel officials down to minor clerks, those in charge all die.", idiomatic: "Thereupon he enacted the Shenming Law, saying, \"When bandit gangs rise, if not discovered, or discovered but capture does not reach the quota, from two-thousand-bushel officials down to minor clerks, those in charge all die." },
  { zh: "」其後小吏畏誅，雖有盜不敢發，恐不能得，坐課累府，府亦使其不言。", literal: "\" Afterward minor clerks feared execution; though there were bandits they dared not report them, fearing they could not obtain the quota and would sit in assessment and burden the prefecture; the prefecture also had them not speak.", idiomatic: "\" Afterward minor clerks feared execution; though there were bandits they dared not report them, fearing they could not meet the quota and would burden the prefecture in assessment; the prefecture also had them keep silent." },
  { zh: "故盜賊多，上下相為匿，以文辭避法焉。", literal: "Therefore bandits were many; superiors and subordinates concealed for one another and used literary phrases to evade the law.", idiomatic: "Therefore bandits were many; superiors and subordinates concealed for one another and used literary phrases to evade the law." },
  { zh: "是時，暴勝之為直指使者，所誅殺二千石以下尤多，威振州郡。", literal: "At this time Bao Sheng-zhi was a direct-pointing envoy; those he executed and killed below two-thousand-bushel rank were especially many; his authority shook provinces and commanderies.", idiomatic: "At this time Bao Sheng-zhi was a direct-pointing envoy; those he executed below two-thousand-bushel rank were especially many; his authority shook provinces and commanderies." },
  { zh: "至勃海，聞郡人雋不疑賢，請與相見。", literal: "Reaching Bohai, he heard that the commandery man Jun Buyi was worthy and requested to meet him.", idiomatic: "Reaching Bohai, he heard that the commandery man Jun Buyi was worthy and requested to meet him." },
  { zh: "不疑容貌尊嚴，衣冠甚偉，勝之躧履起迎，登堂坐定，不疑據地曰：「竊伏海瀕，聞暴公子舊矣，今乃承顏接辭。", literal: "Buyi's appearance was dignified and imposing; his cap and robes very grand; Sheng-zhi slipped off his shoes and rose to greet him; ascending the hall and sitting settled, Buyi leaned on the ground and said: \"Your servant secretly dwells by the sea's edge and has long heard of Master Bao; now I receive your face and exchange words.", idiomatic: "Buyi's appearance was dignified and imposing; his cap and robes very grand; Sheng-zhi slipped off his shoes and rose to greet him; once seated in the hall, Buyi leaned forward and said, \"Your servant dwells secretly by the sea and has long heard of Master Bao; now I receive your face and exchange words." },
  { zh: "凡為吏，太剛則折，太柔則廢，威行，施之以恩，然後樹功揚名，永終天祿。", literal: "In general as an official, too rigid then one breaks, too soft then one is discarded; when authority is established, apply kindness upon it—only then establish merit and raise one's name and eternally complete Heaven's stipend.", idiomatic: "In general as an official, too rigid and one breaks, too soft and one is discarded; when authority is established, apply kindness—only then establish merit, raise one's name, and complete Heaven's stipend to the end." },
  { zh: "」勝之深納其戒；", literal: "\" Sheng-zhi deeply accepted his admonition;", idiomatic: "\" Sheng-zhi deeply accepted his admonition;" },
  { zh: "及還，表薦不疑，上召拜不疑為青州刺史。", literal: "on returning he memorialized recommending Buyi; the emperor summoned and appointed Buyi Governor of Qing Province.", idiomatic: "on returning he memorialized recommending Buyi; the emperor summoned and appointed Buyi Governor of Qing Province." },
  { zh: "濟南王賀亦為繡衣御史，逐捕魏郡群盜，多所縱捨，以奉使不稱免，歎曰：「吾聞活千人，子孫有封，吾所活者萬餘人，後世其興乎！", literal: "Prince He of Jinan also served as embroidered-robes censor, pursued and captured the bandit gangs of Wei Commandery, and released many; because his mission was not fitting he was dismissed; he sighed and said: \"I have heard that saving a thousand lives brings enfeoffment to one's descendants; those your servant saved number more than ten thousand—will posterity flourish!", idiomatic: "Prince He of Jinan also served as embroidered-robes censor, pursued the bandit gangs of Wei Commandery, and released many; because his mission was unsatisfactory he was dismissed; he sighed and said, \"I have heard that saving a thousand lives brings enfeoffment to one's descendants; those I saved number more than ten thousand—will posterity flourish!" },
  { zh: "」----4是歲，以匈奴降者介和王成娩為開陵侯，將樓蘭國兵擊車師；", literal: "\" ----4 That year, the Xiongnu surrenderer King Jiehe Wang Chengwan was made Marquis of Kailing and led Loulan state troops to attack the Cheshi;", idiomatic: "\" ----4 That year the Xiongnu surrenderer King Jiehe Wang Chengwan was made Marquis of Kailing and led Loulan troops to attack Cheshi;" },
  { zh: "匈奴遣右賢王將數萬騎救之，漢兵不利，引去。", literal: "The Xiongnu sent the Right Worthy King to lead tens of thousands of horsemen to rescue them; Han troops were disadvantaged and withdrew.", idiomatic: "The Xiongnu sent the Right Worthy King with tens of thousands of horsemen to rescue them; Han troops were at a disadvantage and withdrew." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
